window.AUTH=window.AUTH||{};window.AUTH["22-660"]={"d":"22-660","id":"2023/22-660","n":"Murray v. UBS Securities, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner Trevor Murray","date":"2023-06-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-660/271844/20230711160716932_22-660%20ts_CORRECTED.pdf","side":"pet","n":88},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-07-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-660/270414/20230705142518131_22-660tsacUnitedStates.pdf","side":"us","n":87},{"k":"respondent","label":"Brief of respondents UBS Securities, LLC, et al.","date":"2023-08-08","url":"https://www.supremecourt.gov/DocketPDF/22/22-660/274894/20230808145455015_Murray%20v.%20UBS%20Merits%20Brief.pdf","side":"res","n":101},{"k":"reply","label":"Reply of petitioner Trevor Murray","date":"2023-09-07","url":"https://www.supremecourt.gov/DocketPDF/22/22-660/279093/20230907142719715_22-660rb.pdfa.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r02_c07d.pdf","tr":true,"items":[{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"op":5,"ar":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"18, 25, 26, 37","1":"25, 26","2":"1, 16, 27","3":"7, 9"}},{"t":"case","label":"Brogan v. United States","cite":"522 U.S. 398","y":1998,"id":"1997/96-1579","sc":1,"op":1,"sum":"In a 7-to-2 decision, the Court held that the imposition of criminal liability for false statements is not limited only to those falsehoods that pervert governmental functions - it applies to statements \"of whatever kind.\" Moreover, even if the \"exculpatory no\" doctrine did apply to statements that do not impede federal functions, Brogan would not benefit from it since his falsehoods were intended to prevent federal agents from uncovering the truth.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"City of Los Angeles Dep’t of Water & Power v. Manhart","cite":"435 U.S. 702","y":1978,"id":"1977/76-1810","sc":1,"sum":"The Court held that the company’s policy was based on aggregate numbers that are not necessarily true for individuals, which violates the Civil Rights Act prohibition of individual discrimination based purely on gender.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Cornelius v. Nutt","cite":"472 U.S. 648","y":1985,"id":"1984/83-1673","sc":1,"sum":"Under §7701(c)(2)(A), the employee-grievant must show error that caused substantial prejudice to his individual rights by possibly affecting the agency's decision.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19, 26, 27, 28, 31, 32","1":"17, 18, 20","2":"15"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharms. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"ar":1,"sum":"The sale of an invention to a third party who is obligated to keep the invention confidential may place the invention “on sale” for purposes of the Leahy-Smith America Invents Act, which bars a person from receiving a patent on an invention that was “in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention,” 35 U. S. C. §102(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27, 29"}},{"t":"case","label":"Int’l Union, UAW v. Johnson Controls, Inc.","cite":"499 U.S. 187","y":1991,"id":"1990/89-1215","sc":1,"op":1,"sum":"Explaining that a prohibition on discrimination “does not depend on why the employer discriminates” or the presence of “malevolent motive”.","sumSrc":"opinion","by":{"0":"37","1":"25"}},{"t":"case","label":"Kentucky Ret. Sys. v. E.E.O.C.","cite":"5554 U.S. 135","y":2008,"url":"https://supreme.justia.com/cases/federal/us/5554/135/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Kewley v. Dep’t of Health & Hum. Servs.","cite":"153 F.3d 1357","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/153/1357/","by":{"0":"29","1":"20"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"op":2,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"0":"3, 4, 38, 39","1":"7, 8, 27, 31, 32","2":"2, 13, 20, 26, 37, 39, 44, 45"}},{"t":"case","label":"Lawson v. PPG Architectural Finishes, Inc.","cite":"12 Cal. 5th 703","y":2022,"url":"https://www.courtlistener.com/c/Cal.%205th/12/703/","by":{"0":"33"}},{"t":"case","label":"Marano v. Dep’t of Justice","cite":"2 F.3d 1137","y":1993,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/2/1137/","op":1,"ar":3,"by":{"0":"19, 29, 30, 31","1":"6, 7, 19, 20, 22, 30","2":"13, 42, 43"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"ar":2,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"24","3":"9"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"ar":4,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"0":"9","1":"27, 28","2":"18, 19, 20"}},{"t":"case","label":"TransAm Trucking, Inc. v. Admin. Rev. Bd.","cite":"833 F.3d 1206","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/833/1206/","by":{"0":"32"}},{"t":"case","label":"Vill. of Arlington Heights v. Metro. Housing Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Weinberger v. Cath. Action of Hawaii/Peace Educ. Project","cite":"454 U.S. 139","y":1981,"id":"1981/81-1377","sc":1,"sum":"The Court of Appeals erred in requiring the Navy to prepare and release to the public a \"Hypothetical Environmental Impact Statement.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 22"}},{"t":"case","label":"In re Williams v. QVC, Inc., ARB Case No. 2020-0019","cite":"2023 WL 1927097","y":2023,"court":"ARB Jan. 17","by":{"0":"32"}},{"t":"case","label":"Williams v. Trans States Airlines, Inc.","cite":"281 S.W.3d 854","y":2009,"court":"Mo. App.","url":"https://www.courtlistener.com/c/S.W.3d/281/854/","by":{"0":"33"}},{"t":"case","label":"Wygant v. Jackson Bd. of Educ.","cite":"476 U.S. 267","y":1986,"id":"1985/84-1340","sc":1,"sum":"In a 5-to-4 decision, the Court argued that Wygant's layoff stemmed from race and, therefore, violated the Equal Protection Clause. The Court noted that the government, when embarking on affirmative action, had two duties: first, to justify racial classification with a compelling state interest and second, to demonstrate that its chosen means were narrowly tailored to its purpose.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Wynn v. Illinois Dep’t of Hum. Servs.","cite":"81 N.E.3d 28","y":2017,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.3d/81/28/","by":{"0":"33"}},{"t":"usc","label":"6 U.S.C. § 1142","url":"https://www.law.cornell.edu/uscode/text/6/1142","subs":["(c)(2)(B)"],"by":{"0":"6"}},{"t":"usc","label":"49 U.S.C. § 20109","url":"https://www.law.cornell.edu/uscode/text/49/20109","subs":["(d)(2)(A)(i)","(c)(2)","(d)","(d)(2)"],"by":{"0":"7, 32","1":"8, 33, 8"}},{"t":"usc","label":"49 U.S.C. § 31105","url":"https://www.law.cornell.edu/uscode/text/49/31105","subs":["(b)(1)","(b)"],"by":{"0":"7, 32","1":"8, 33"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"24, 37","1":"25","3":"13"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)(1)","(m)","(a)(2)"],"by":{"0":"25, 24","2":"22, 23, 31, 22, 23, 31, 22, 23, 31"}},{"t":"law","label":"Pub. L. No. 111-281","url":"https://www.govinfo.gov/link/plaw/111/public/281","by":{"0":"7"}},{"t":"usc","label":"46 U.S.C. § 2114","url":"https://www.law.cornell.edu/uscode/text/46/2114","subs":["(b)","(b)(2)(B)"],"by":{"0":"7, 33"}},{"t":"usc","label":"15 U.S.C. § 2087","url":"https://www.law.cornell.edu/uscode/text/15/2087","subs":["(b)(2)(B)","(b)"],"stext":{"head":"§2087. Whistleblower protection","paras":[[0,"(a) No manufacturer, private labeler, distributor, or retailer,1 may discharge an employee or otherwise discriminate against an employee with respect to compensation, terms, conditions, or privileges of employment because the employee, whether at the employee's initiative or in the ordinary course of the employee's duties (or any person acting pursuant to a request of the employee)—"],[1,"(1) provided, caused to be provided, or is about to provide or cause to be provided to the employer, the Federal Government, or the attorney general of a State information relating to any violation of, or any act or omission the employee reasonably believes to be a violation of any provision of this chapter or any other Act enforced by the Commission, or any order, rule, regulation, standard, or ban under any such Acts;"],[1,"(2) testified or is about to testify in a proceeding concerning such violation;"],[1,"(3) assisted or participated or is about to assist or participate in such a proceeding; or"],[1,"(4) objected to, or refused to participate in, any activity, policy, practice, or assigned task that the employee (or other such person) reasonably believed to be in violation of any provision of this chapter or any other Act enforced by the Commission, or any order, rule, regulation, standard, or ban under any such Acts."],[0,"(b)(1) A person who believes that he or she has been discharged or otherwise discriminated against by any person in violation of subsection (a) may, not later than 180 days after the date on which such violation occurs, file (or have any person file on his or her behalf) a complaint with the Secretary of Labor alleging such discharge or discrimination and identifying the person responsible for such act. Upon receipt of such a complaint, the Secretary shall notify, in writing, the person named in the complaint of the filing of the complaint, of the allegations contained in the complaint, of the substance of evidence supporting the complaint, and of the opportunities that will be afforded to such person under paragraph (2)."],[0,"(2)(A) Not later than 60 days after the date of receipt of a complaint filed under paragraph (1) and after affording the complainant and the person named in the complaint an opportunity to submit to the Secretary a written response to the complaint and an opportunity to meet with a representative of the Secretary to present statements from witnesses, the Secretary shall initiate an investigation and determine whether there is reasonable cause to believe that the complaint has merit and notify, in writing, the complainant and the person alleged to have committed a violation of subsection (a) of the Secretary's findings. If the Secretary concludes that there is reasonable cause to believe that a violation of subsection (a) has occurred, the Secretary shall accompany the Secretary's findings with a preliminary order providing the relief prescribed by paragraph (3)(B). Not later than 30 days after the date of notification of findings under this paragraph, either the person alleged to have committed the violation or the complainant may file objections to the findings or preliminary order, or both, and request a hearing on the record. The filing of such objections shall not operate to stay any reinstatement remedy contained in the preliminary order. Any such hearing shall be conducted expeditiously. If a hearing is not requested in such 30-day period, the preliminary order shall be deemed a final order that is not subject to judicial review."],[0,"(B)(i) The Secretary shall dismiss a complaint filed under this subsection and shall not conduct an investigation otherwise required under subparagraph (A) unless the complainant makes a prima facie showing that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(ii) Notwithstanding a finding by the Secretary that the complainant has made the showing required under clause (i), no investigation otherwise required under subparagraph (A) shall be conducted if the employer demonstrates, by clear and convincing evidence, that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[0,"(iii) The Secretary may determine that a violation of subsection (a) has occurred only if the complainant demonstrates that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(iv) Relief may not be ordered under subparagraph (A) if the employer demonstrates by clear and convincing evidence that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[0,"(3)(A) Not later than 120 days after the date of conclusion of any hearing under paragraph (2), the Secretary shall issue a final order providing the relief prescribed by this paragraph or denying the complaint. At any time before issuance of a final order, a proceeding under this subsection may be terminated on the basis of a settlement agreement entered into by the Secretary, the complainant, and the person alleged to have committed the violation."],[0,"(B) If, in response to a complaint filed under paragraph (1), the Secretary determines that a violation of subsection (a) has occurred, the Secretary shall order the person who committed such violation—"],[1,"(i) to take affirmative action to abate the violation;"],[1,"(ii) to reinstate the complainant to his or her former position together with compensation (including back pay) and restore the terms, conditions, and privileges associated with his or her employment; and"],[1,"(iii) to provide compensatory damages to the complainant."],[0,"If such an order is issued under this paragraph, the Secretary, at the request of the complainant, shall assess against the person against whom the order is issued a sum equal to the aggregate amount of all costs and expenses (including attorneys' and expert witness fees) reasonably incurred, as determined by the Secretary, by the complainant for, or in connection with, the bringing of the complaint upon which the order was issued."],[0,"(C) If the Secretary finds that a complaint under paragraph (1) is frivolous or has been brought in bad faith, the Secretary may award to the prevailing employer a reasonable attorneys' fee, not exceeding $1,000, to be paid by the complainant."],[0,"(4) If the Secretary has not issued a final decision within 210 days after the filing of the complaint, or within 90 days after receiving a written determination, the complainant may bring an action at law or equity for de novo review in the appropriate district court of the United States with jurisdiction, which shall have jurisdiction over such an action without regard to the amount in controversy, and which action shall, at the request of either party to such action, be tried by the court with a jury. The proceedings shall be governed by the same legal burdens of proof specified in paragraph (2)(B). The court shall have jurisdiction to grant all relief necessary to make the employee whole, including injunctive relief and compensatory damages, including—"],[1,"(A) reinstatement with the same seniority status that the employee would have had, but for the discharge or discrimination;"],[1,"(B) the amount of back pay, with interest; and"],[1,"(C) compensation for any special damages sustained as a result of the discharge or discrimination, including litigation costs, expert witness fees, and reasonable attorney's fees."],[0,"(5)(A) Unless the complainant brings an action under paragraph (4), any person adversely affected or aggrieved by a final order issued under paragraph (3) may obtain review of the order in the United States Court of Appeals for the circuit in which the violation, with respect to which the order was issued, allegedly occurred or the circuit in which the complainant resided on the date of such violation. The petition for review must be filed not later than 60 days after the date of the issuance of the final order of the Secretary. Review shall conform to chapter 7 of title 5. The commencement of proceedings under this subparagraph shall not, unless ordered by the court, operate as a stay of the order."],[0,"(B) An order of the Secretary with respect to which review could have been obtained under subparagraph (A) shall not be subject to judicial review in any criminal or other civil proceeding."],[0,"(6) Whenever any person has failed to comply with an order issued under paragraph (3), the Secretary may file a civil action in the United States district court for the district in which the violation was found to occur, or in the United States district court for the District of Columbia, to enforce such order. In actions brought under this paragraph, the district courts shall have jurisdiction to grant all appropriate relief including, but not limited to, injunctive relief and compensatory damages."],[0,"(7)(A) A person on whose behalf an order was issued under paragraph (3) may commence a civil action against the person to whom such order was issued to require compliance with such order. The appropriate United States district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce such order."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/2087?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2087. Whistleblower protection","tname":"Commerce and Trade","by":{"0":"32, 7","1":"7"}},{"t":"usc","label":"15 U.S.C. § 7a-3","url":"https://www.law.cornell.edu/uscode/text/15/7a-3","subs":["(b)(2)(B)","(b)"],"stext":{"head":"§7a–3. Anti-retaliation protection for whistleblowers","paras":[[0,"(a) Whistleblower protections for employees, contractors, subcontractors, and agents"],[0,"(1) In general"],[1,"No employer may discharge, demote, suspend, threaten, harass, or in any other manner discriminate against a covered individual in the terms and conditions of employment of the covered individual because of any lawful act done by the covered individual—"],[2,"(A) to provide or cause to be provided to the Federal Government or a person with supervisory authority over the covered individual (or such other person working for the employer who has the authority to investigate, discover, or terminate misconduct) information relating to—"],[3,"(i) any violation of, or any act or omission the covered individual reasonably believes to be a violation of, the antitrust laws; or"],[3,"(ii) any violation of, or any act or omission the covered individual reasonably believes to be a violation of, another criminal law committed in conjunction with a potential violation of the antitrust laws or in conjunction with an investigation by the Department of Justice of a potential violation of the antitrust laws; or"],[2,"(B) to cause to be filed, testify in, participate in, or otherwise assist a Federal Government investigation or a Federal Government proceeding filed or about to be filed (with any knowledge of the employer) relating to—"],[3,"(i) any violation of, or any act or omission the covered individual reasonably believes to be a violation of, the antitrust laws; or"],[3,"(ii) any violation of, or any act or omission the covered individual reasonably believes to be a violation of, another criminal law committed in conjunction with a potential violation of the antitrust laws or in conjunction with an investigation by the Department of Justice of a potential violation of the antitrust laws."],[0,"(2) Limitation on protections"],[1,"Paragraph (1) shall not apply to any covered individual if—"],[2,"(A) the covered individual planned and initiated a violation or attempted violation of the antitrust laws;"],[2,"(B) the covered individual planned and initiated a violation or attempted violation of another criminal law in conjunction with a violation or attempted violation of the antitrust laws; or"],[2,"(C) the covered individual planned and initiated an obstruction or attempted obstruction of an investigation by the Department of Justice of a violation of the antitrust laws."],[0,"(3) Definitions"],[1,"In this section:"],[0,"(A) Antitrust laws"],[2,"The term \"antitrust laws\" means section 1 or 3 of this title."],[0,"(B) Covered individual"],[2,"The term \"covered individual\" means an employee, contractor, subcontractor, or agent of an employer."],[0,"(C) Employer"],[2,"The term \"employer\" means a person, or any officer, employee, contractor, subcontractor, or agent of such person."],[0,"(D) Federal Government"],[2,"The term \"Federal Government\" means—"],[3,"(i) a Federal regulatory or law enforcement agency; or"],[3,"(ii) any Member of Congress or committee of Congress."],[0,"(E) Person"],[2,"The term \"person\" has the same meaning as in subsection (a) of section 12 of this title."],[0,"(4) Rule of construction"],[1,"The term \"violation\", with respect to the antitrust laws, shall not be construed to include a civil violation of any law that is not also a criminal violation."],[0,"(b) Enforcement action"],[0,"(1) In general"],[1,"A covered individual who alleges discharge or other discrimination by any employer in violation of subsection (a) may seek relief under subsection (c) by—"],[2,"(A) filing a complaint with the Secretary of Labor; or"],[2,"(B) if the Secretary of Labor has not issued a final decision within 180 days of the filing of the complaint and there is no showing that such delay is due to the bad faith of the claimant, bringing an action at law or equity for de novo review in the appropriate district court of the United States, which shall have jurisdiction over such an action without regard to the amount in controversy."],[0,"(2) Procedure"],[0,"(A) In general"],[2,"A complaint filed with the Secretary of Labor under paragraph (1)(A) shall be governed under the rules and procedures set forth in section 42121(b) of title 49."],[0,"(B) Exception"],[2,"Notification made under section 42121(b)(1) of title 49 shall be made to any individual named in the complaint and to the employer."],[0,"(C) Burdens of proof"],[2,"An action brought under paragraph (1)(B) shall be governed by the legal burdens of proof set forth in section 42121(b) of title 49."],[0,"(D) Statute of limitations"],[2,"A complaint under paragraph (1)(A) shall be filed with the Secretary of Labor not later than 180 days after the date on which the violation occurs."],[0,"(E) Civil actions to enforce"],[2,"If a person fails to comply with an order or preliminary order issued by the Secretary of Labor pursuant to the procedures set forth in section 42121(b) of title 49, the Secretary of Labor or the person on whose behalf the order was issued may bring a civil action to enforce the order in the district court of the United States for the judicial district in which the violation occurred."],[0,"(c) Remedies"],[0,"(1) In general"],[1,"A covered individual prevailing in any action under subsection (b)(1) shall be entitled to all relief necessary to make the covered individual whole."],[0,"(2) Compensatory damages"],[1,"Relief for any action under paragraph (1) shall include—"],[2,"(A) reinstatement with the same seniority status that the covered individual would have had, but for the discrimination;"],[2,"(B) the amount of back pay, with interest; and"],[2,"(C) compensation for any special damages sustained as a result of the discrimination including litigation costs, expert witness fees, and reasonable attorney's fees."],[0,"(d) Rights retained by whistleblowers"],[0,"Nothing in this section shall be deemed to diminish the rights, privileges, or remedies of any covered individual under any Federal or State law, or under any collective bargaining agreement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7a-3?type=usc&year=mostrecent&link-type=html"},"head":"§7a–3. Anti-retaliation protection for whistleblowers","tname":"Commerce and Trade","by":{"0":"7, 7","1":"8"}},{"t":"law","label":"Dodd-Frank Wall Street Reform & Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"0":"7"}},{"t":"usc","label":"12 U.S.C. § 5567","url":"https://www.law.cornell.edu/uscode/text/12/5567","subs":["(c)(3)"],"by":{"0":"7, 33"}},{"t":"usc","label":"21 U.S.C. § 399d","url":"https://www.law.cornell.edu/uscode/text/21/399d","subs":["(b)(2)(C)","(b)"],"stext":{"head":"§399d. Employee protections","paras":[[0,"(a) In general"],[0,"No entity engaged in the manufacture, processing, packing, transporting, distribution, reception, holding, or importation of food may discharge an employee or otherwise discriminate against an employee with respect to compensation, terms, conditions, or privileges of employment because the employee, whether at the employee's initiative or in the ordinary course of the employee's duties (or any person acting pursuant to a request of the employee)—"],[1,"(1) provided, caused to be provided, or is about to provide or cause to be provided to the employer, the Federal Government, or the attorney general of a State information relating to any violation of, or any act or omission the employee reasonably believes to be a violation of any provision of this chapter or any order, rule, regulation, standard, or ban under this chapter, or any order, rule, regulation, standard, or ban under this chapter; 1"],[1,"(2) testified or is about to testify in a proceeding concerning such violation;"],[1,"(3) assisted or participated or is about to assist or participate in such a proceeding; or"],[1,"(4) objected to, or refused to participate in, any activity, policy, practice, or assigned task that the employee (or other such person) reasonably believed to be in violation of any provision of this chapter, or any order, rule, regulation, standard, or ban under this chapter."],[0,"(b) Process"],[0,"(1) In general"],[1,"A person who believes that he or she has been discharged or otherwise discriminated against by any person in violation of subsection (a) may, not later than 180 days after the date on which such violation occurs, file (or have any person file on his or her behalf) a complaint with the Secretary of Labor (referred to in this section as the \"Secretary\") alleging such discharge or discrimination and identifying the person responsible for such act. Upon receipt of such a complaint, the Secretary shall notify, in writing, the person named in the complaint of the filing of the complaint, of the allegations contained in the complaint, of the substance of evidence supporting the complaint, and of the opportunities that will be afforded to such person under paragraph (2)."],[0,"(2) Investigation"],[0,"(A) In general"],[2,"Not later than 60 days after the date of receipt of a complaint filed under paragraph (1) and after affording the complainant and the person named in the complaint an opportunity to submit to the Secretary a written response to the complaint and an opportunity to meet with a representative of the Secretary to present statements from witnesses, the Secretary shall initiate an investigation and determine whether there is reasonable cause to believe that the complaint has merit and notify, in writing, the complainant and the person alleged to have committed a violation of subsection (a) of the Secretary's findings."],[0,"(B) Reasonable cause found; preliminary order"],[2,"If the Secretary concludes that there is reasonable cause to believe that a violation of subsection (a) has occurred, the Secretary shall accompany the Secretary's findings with a preliminary order providing the relief prescribed by paragraph (3)(B). Not later than 30 days after the date of notification of findings under this paragraph, the person alleged to have committed the violation or the complainant may file objections to the findings or preliminary order, or both, and request a hearing on the record. The filing of such objections shall not operate to stay any reinstatement remedy contained in the preliminary order. Any such hearing shall be conducted expeditiously. If a hearing is not requested in such 30-day period, the preliminary order shall be deemed a final order that is not subject to judicial review."],[0,"(C) Dismissal of complaint"],[0,"(i) Standard for complainant"],[3,"The Secretary shall dismiss a complaint filed under this subsection and shall not conduct an investigation otherwise required under subparagraph (A) unless the complainant makes a prima facie showing that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(ii) Standard for employer"],[3,"Notwithstanding a finding by the Secretary that the complainant has made the showing required under clause (i), no investigation otherwise required under subparagraph (A) shall be conducted if the employer demonstrates, by clear and convincing evidence, that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[0,"(iii) Violation standard"],[3,"The Secretary may determine that a violation of subsection (a) has occurred only if the complainant demonstrates that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(iv) Relief standard"],[3,"Relief may not be ordered under subparagraph (A) if the employer demonstrates by clear and convincing evidence that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[0,"(3) Final order"],[0,"(A) In general"],[2,"Not later than 120 days after the date of conclusion of any hearing under paragraph (2), the Secretary shall issue a final order providing the relief prescribed by this paragraph or denying the complaint. At any time before issuance of a final order, a proceeding under this subsection may be terminated on the basis of a settlement agreement entered into by the Secretary, the complainant, and the person alleged to have committed the violation."],[0,"(B) Content of order"],[2,"If, in response to a complaint filed under paragraph (1), the Secretary determines that a violation of subsection (a) has occurred, the Secretary shall order the person who committed such violation—"],[3,"(i) to take affirmative action to abate the violation;"],[3,"(ii) to reinstate the complainant to his or her former position together with compensation (including back pay) and restore the terms, conditions, and privileges associated with his or her employment; and"],[3,"(iii) to provide compensatory damages to the complainant."],[0,"(C) Penalty"],[2,"If such an order is issued under this paragraph, the Secretary, at the request of the complainant, shall assess against the person against whom the order is issued a sum equal to the aggregate amount of all costs and expenses (including attorneys' and expert witness fees) reasonably incurred, as determined by the Secretary, by the complainant for, or in connection with, the bringing of the complaint upon which the order was issued."],[0,"(D) Bad faith claim"],[2,"If the Secretary finds that a complaint under paragraph (1) is frivolous or has been brought in bad faith, the Secretary may award to the prevailing employer a reasonable attorneys' fee, not exceeding $1,000, to be paid by the complainant."],[0,"(4) Action in court"],[0,"(A) In general"],[2,"If the Secretary has not issued a final decision within 210 days after the filing of the complaint, or within 90 days after receiving a written determination, the complainant may bring an action at law or equity for de novo review in the appropriate district court of the United States with jurisdiction, which shall have jurisdiction over such an action without regard to the amount in controversy, and which action shall, at the request of either party to such action, be tried by the court with a jury. The proceedings shall be governed by the same legal burdens of proof specified in paragraph (2)(C)."],[0,"(B) Relief"],[2,"The court shall have jurisdiction to grant all relief necessary to make the employee whole, including injunctive relief and compensatory damages, including—"],[3,"(i) reinstatement with the same seniority status that the employee would have had, but for the discharge or discrimination;"],[3,"(ii) the amount of back pay, with interest; and"],[3,"(iii) compensation for any special damages sustained as a result of the discharge or discrimination, including litigation costs, expert witness fees, and reasonable attorney's fees."],[0,"(5) Review"],[0,"(A) In general"],[2,"Unless the complainant brings an action under paragraph (4), any person adversely affected or aggrieved by a final order issued under paragraph (3) may obtain review of the order in the United States Court of Appeals for the circuit in which the violation, with respect to which the order was issued, allegedly occurred or the circuit in which the complainant resided on the date of such violation. The petition for review must be filed not later than 60 days after the date of the issuance of the final order of the Secretary. Review shall conform to chapter 7 of title 5. The commencement of proceedings under this subparagraph shall not, unless ordered by the court, operate as a stay of the order."],[0,"(B) No judicial review"],[2,"An order of the Secretary with respect to which review could have been obtained under subparagraph (A) shall not be subject to judicial review in any criminal or other civil proceeding."],[0,"(6) Failure to comply with order"],[1,"Whenever any person has failed to comply with an order issued under paragraph (3), the Secretary may file a civil action in the United States district court for the district in which the violation was found to occur, or in the United States district court for the District of Columbia, to enforce such order. In actions brought under this paragraph, the district courts shall have jurisdiction to grant all appropriate relief including, but not limited to, injunctive relief and compensatory damages."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/399d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§399d. Employee protections","tname":"Food and Drugs","by":{"0":"7, 33","1":"7"}},{"t":"law","label":"Moving Ahead for Progress in the 21st Century Act, Pub. L. No. 112-141","url":"https://www.govinfo.gov/link/plaw/112/public/141","by":{"0":"7"}},{"t":"usc","label":"49 U.S.C. § 30171","url":"https://www.law.cornell.edu/uscode/text/49/30171","subs":["(b)(2)(B)","(b)"],"stext":{"head":"§30171. Protection of employees providing motor vehicle safety information","paras":[[0,"(a) Discrimination Against Employees of Manufacturers, Part Suppliers, and Dealerships.—No motor vehicle manufacturer, part supplier, or dealership may discharge an employee or otherwise discriminate against an employee with respect to compensation, terms, conditions, or privileges of employment because the employee (or any person acting pursuant to a request of the employee)—"],[1,"(1) provided, caused to be provided, or is about to provide (with any knowledge of the employer) or cause to be provided to the employer or the Secretary of Transportation information relating to any motor vehicle defect, noncompliance, or any violation or alleged violation of any notification or reporting requirement of this chapter;"],[1,"(2) has filed, caused to be filed, or is about to file (with any knowledge of the employer) or cause to be filed a proceeding relating to any violation or alleged violation of any motor vehicle defect, noncompliance, or any violation or alleged violation of any notification or reporting requirement of this chapter;"],[1,"(3) testified or is about to testify in such a proceeding;"],[1,"(4) assisted or participated or is about to assist or participate in such a proceeding; or"],[1,"(5) objected to, or refused to participate in, any activity that the employee reasonably believed to be in violation of any provision of chapter 301 of this title, or any order, rule, regulation, standard, or ban under such provision."],[0,"(b) Complaint Procedure.—"],[1,"(1) Filing and notification.—A person who believes that he or she has been discharged or otherwise discriminated against by any person in violation of subsection (a) may file (or have any person file on his or her behalf), not later than 180 days after the date on which such violation occurs, a complaint with the Secretary of Labor (hereinafter in this section referred to as the \"Secretary\") alleging such discharge or discrimination. Upon receipt of such a complaint, the Secretary shall notify, in writing, the person named in the complaint of the filing of the complaint, of the allegations contained in the complaint, of the substance of evidence supporting the complaint, and of the opportunities that will be afforded to such person under paragraph (2)."],[1,"(2) Investigation; preliminary order.—"],[2,"(A) In general.—Not later than 60 days after the date of receipt of a complaint filed under paragraph (1) and after affording the person named in the complaint an opportunity to submit to the Secretary a written response to the complaint and an opportunity to meet with a representative of the Secretary to present statements from witnesses, the Secretary shall conduct an investigation and determine whether there is reasonable cause to believe that the complaint has merit and notify, in writing, the complainant and the person alleged to have committed a violation of subsection (a) of the Secretary's findings. If the Secretary concludes that there is a reasonable cause to believe that a violation of subsection (a) has occurred, the Secretary shall accompany the Secretary's findings with a preliminary order providing the relief prescribed by paragraph (3)(B). Not later than 30 days after the date of notification of findings under this paragraph, either the person alleged to have committed the violation or the complainant may file objections to the findings or preliminary order, or both, and request a hearing on the record. The filing of such objections shall not operate to stay any reinstatement remedy contained in the preliminary order. Such hearings shall be conducted expeditiously. If a hearing is not requested in such 30-day period, the preliminary order shall be deemed a final order that is not subject to judicial review."],[2,"(B) Requirements.—"],[3,"(i) Required showing by complainant.—The Secretary shall dismiss a complaint filed under this subsection and shall not conduct an investigation otherwise required under subparagraph (A) unless the complainant makes a prima facie showing that any behavior described in paragraphs (1) through (5) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[3,"(ii) Showing by employer.—Notwithstanding a finding by the Secretary that the complainant has made the showing required under clause (i), no investigation otherwise required under subparagraph (A) shall be conducted if the employer demonstrates, by clear and convincing evidence, that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[3,"(iii) Criteria for determination by secretary.—The Secretary may determine that a violation of subsection (a) has occurred only if the complainant demonstrates that any behavior described in paragraphs (1) through (5) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[3,"(iv) Prohibition.—Relief may not be ordered under subparagraph (A) if the employer demonstrates, by clear and convincing evidence, that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[1,"(3) Final order.—"],[2,"(A) Deadline for issuance; settlement agreements.—Not later than 120 days after the date of conclusion of a hearing under paragraph (2), the Secretary shall issue a final order providing the relief prescribed by this paragraph or denying the complaint. At any time before issuance of a final order, a proceeding under this subsection may be terminated on the basis of a settlement agreement entered into by the Secretary, the complainant, and the person alleged to have committed the violation."],[2,"(B) Remedy.—If, in response to a complaint filed under paragraph (1), the Secretary determines that a violation of subsection (a) has occurred, the Secretary shall order the person who committed such violation—"],[3,"(i) to take affirmative action to abate the violation;"],[3,"(ii) to reinstate the complainant to his or her former position together with the compensation (including back pay) and restore the terms, conditions, and privileges associated with his or her employment; and"],[3,"(iii) to provide compensatory damages to the complainant."],[2,"(C) Attorneys' fees.—If such an order is issued under this paragraph, the Secretary, at the request of the complainant, shall assess against the person against whom the order is issued a sum equal to the aggregate amount of all costs and expenses (including attorneys' and expert witness fees) reasonably incurred, as determined by the Secretary, by the complainant for, or in connection with, bringing the complaint upon which the order was issued."],[2,"(D) Frivolous complaints.—If the Secretary determines that a complaint under paragraph (1) is frivolous or has been brought in bad faith, the Secretary may award to the prevailing employer a reasonable attorney's fee not exceeding $1,000."],[2,"(E) De novo review.—With respect to a complaint under paragraph (1), if the Secretary has not issued a final decision within 210 days after the filing of the complaint and if the delay is not due to the bad faith of the employee, the employee may bring an original action at law or equity for de novo review in the appropriate district court of the United States, which shall have jurisdiction over such an action without regard to the amount in controversy, and which action shall, at the request of either party to the action, be tried by the court with a jury. The action shall be governed by the same legal burdens of proof specified in paragraph (2)(B) for review by the Secretary."],[1,"(4) Review.—"],[2,"(A) Appeal to court of appeals.—Any person adversely affected or aggrieved by an order issued under paragraph (3) may obtain review of the order in the United States Court of Appeals for the circuit in which the violation, with respect to which the order was issued, allegedly occurred or the circuit in which the complainant resided on the date of such violation. The petition for review shall be filed not later than 60 days after the date of the issuance of the final order of the Secretary. Review shall conform to chapter 7 of title 5. The commencement of proceedings under this subparagraph shall not, unless ordered by the court, operate as a stay of the order."],[2,"(B) Limitation on collateral attack.—An order of the Secretary with respect to which review could have been obtained under subparagraph (A) shall not be subject to judicial review in any criminal or other civil proceeding."],[1,"(5) Enforcement of order by secretary.—Whenever any person fails to comply with an order issued under paragraph (3), the Secretary may file a civil action in the United States district court for the district in which the violation was found to occur to enforce such order. In actions brought under this paragraph, the district courts shall have jurisdiction to grant all appropriate relief, including injunctive relief and compensatory damages."],[1,"(6) Enforcement of order by parties.—"],[2,"(A) Commencement of action.—A person on whose behalf an order was issued under paragraph (3) may commence a civil action against the person to whom such order was issued to require compliance with such order. The appropriate United States district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce such order."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/30171?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§30171. Protection of employees providing motor vehicle safety information","tname":"Transportation","by":{"0":"7, 33","1":"7"}},{"t":"law","label":"Pub. L. No. 112-239","url":"https://www.govinfo.gov/link/plaw/112/public/239","by":{"0":"7"}},{"t":"usc","label":"10 U.S.C. § 4701","url":"https://www.law.cornell.edu/uscode/text/10/4701","subs":["(c)(6)"],"stext":{"head":"§4701. Contractor employees: protection from reprisal for disclosure of certain information","paras":[[0,"(a) Prohibition of Reprisals.—(1) An employee of a contractor, subcontractor, grantee, or subgrantee or personal services contractor may not be discharged, demoted, or otherwise discriminated against as a reprisal for disclosing to a person or body described in paragraph (2) information that the employee reasonably believes is evidence of the following:"],[1,"(A) Gross mismanagement of a Department of Defense contract or grant, a gross waste of Department funds, an abuse of authority relating to a Department contract or grant, or a violation of law, rule, or regulation related to a Department contract (including the competition for or negotiation of a contract) or grant."],[1,"(B) Gross mismanagement of a National Aeronautics and Space Administration contract or grant, a gross waste of Administration funds, an abuse of authority relating to an Administration contract or grant, or a violation of law, rule, or regulation related to an Administration contract (including the competition for or negotiation of a contract) or grant."],[1,"(C) A substantial and specific danger to public health or safety."],[0,"(2) The persons and bodies described in this paragraph are the persons and bodies as follows:"],[1,"(A) A Member of Congress or a representative of a committee of Congress."],[1,"(B) An Inspector General."],[1,"(C) The Government Accountability Office."],[1,"(D) An employee of the Department of Defense or the National Aeronautics and Space Administration, as applicable, responsible for contract oversight or management."],[1,"(E) An authorized official of the Department of Justice or other law enforcement agency."],[1,"(F) A court or grand jury."],[1,"(G) A management official or other employee of the contractor, subcontractor, grantee, subgrantee, or personal services contractor who has the responsibility to investigate, discover, or address misconduct."],[0,"(3) For the purposes of paragraph (1)—"],[1,"(A) an employee who initiates or provides evidence of contractor, subcontractor, grantee, subgrantee, or personal services contractor misconduct in any judicial or administrative proceeding relating to waste, fraud, or abuse on a Department of Defense or National Aeronautics and Space Administration contract or grant shall be deemed to have made a disclosure covered by such paragraph; and"],[1,"(B) a reprisal described in paragraph (1) is prohibited even if it is undertaken at the request of a Department or Administration official, unless the request takes the form of a nondiscretionary directive and is within the authority of the Department or Administration official making the request."],[0,"(b) Investigation of Complaints.—(1) A person who believes that the person has been subjected to a reprisal prohibited by subsection (a) may submit a complaint to the Inspector General of the Department of Defense, or the Inspector General of the National Aeronautics and Space Administration in the case of a complaint regarding the National Aeronautics and Space Administration. Unless the Inspector General determines that the complaint is frivolous, fails to allege a violation of the prohibition in subsection (a), or has previously been addressed in another Federal or State judicial or administrative proceeding initiated by the complainant, the Inspector General shall investigate the complaint and, upon completion of such investigation, submit a report of the findings of the investigation to the person, the contractor, subcontractor, grantee, subgrantee, or personal services contractor concerned, and the head of the agency."],[0,"(2)(A) Except as provided under subparagraph (B), the Inspector General shall make a determination that a complaint is frivolous, fails to allege a violation of the prohibition in subsection (a), or has previously been addressed in another Federal or State judicial or administrative proceeding initiated by the complainant or submit a report under paragraph (1) within 180 days after receiving the complaint."],[0,"(B) If the Inspector General is unable to complete an investigation in time to submit a report within the 180-day period specified in subparagraph (A) and the person submitting the complaint agrees to an extension of time, the Inspector General shall submit a report under paragraph (1) within such additional period of time, up to 180 days, as shall be agreed upon between the Inspector General and the person submitting the complaint."],[0,"(3) The Inspector General may not respond to any inquiry or disclose any information from or about any person alleging the reprisal, except to the extent that such response or disclosure is—"],[1,"(A) made with the consent of the person alleging the reprisal;"],[1,"(B) made in accordance with the provisions of section 552a of title 5 or as required by any other applicable Federal law; or"],[1,"(C) necessary to conduct an investigation of the alleged reprisal."],[0,"(4) A complaint may not be brought under this subsection more than three years after the date on which the alleged reprisal took place."],[0,"(c) Remedy and Enforcement Authority.—(1) Not later than 30 days after receiving an Inspector General report pursuant to subsection (b), the head of the agency concerned shall determine whether there is sufficient basis to conclude that the contractor, subcontractor, grantee, subgrantee, or personal services contractor concerned has subjected the complainant to a reprisal prohibited by subsection (a) and shall either issue an order denying relief or shall take one or more of the following actions:"],[1,"(A) Order the contractor, subcontractor, grantee, subgrantee, or personal services contractor to take affirmative action to abate the reprisal."],[1,"(B) Order the contractor, subcontractor, grantee, subgrantee, or personal services contractor to reinstate the person to the position that the person held before the reprisal, together with compensatory damages (including back pay), employment benefits, and other terms and conditions of employment that would apply to the person in that position if the reprisal had not been taken."],[1,"(C) Order the contractor, subcontractor, grantee, subgrantee, or personal services contractor to pay the complainant an amount equal to the aggregate amount of all costs and expenses (including attorneys' fees and expert witnesses' fees) that were reasonably incurred by the complainant for, or in connection with, bringing the complaint regarding the reprisal, as determined by the head of the agency."],[1,"(D) Consider disciplinary or corrective action against any official of the Department of Defense."],[0,"(2) Not later than 30 days after receiving an Inspector General report pursuant to subsection (b), the head of the agency concerned shall notify the complainant and the Inspector General, in writing, of either the actions ordered or the decision to deny relief. After such notification, if the head of the agency concerned changes the actions ordered or the decision to deny relief, the head of the agency concerned shall notify the complainant and the Inspector General, in writing, of the change not later than 30 days after the change occurs."],[0,"(3) If the head of an executive agency issues an order denying relief under paragraph (1) or has not issued an order within 210 days after the submission of a complaint under subsection (b), or in the case of an extension of time under paragraph (2)(B) of such subsection, not later than 30 days after the expiration of the extension of time, and there is no showing that such delay is due to the bad faith of the complainant, the complainant shall be deemed to have exhausted all administrative remedies with respect to the complaint, and the complainant may bring a de novo action at law or equity against the contractor, subcontractor, grantee, subgrantee, or personal services contractor to seek compensatory damages and other relief available under this section in the appropriate district court of the United States, which shall have jurisdiction over such an action without regard to the amount in controversy. Such an action shall, at the request of either party to the action, be tried by the court with a jury. An action under this paragraph may not be brought more than two years after the date on which remedies are deemed to have been exhausted."],[0,"(4) An Inspector General determination and an agency head order denying relief under paragraph (3) shall be admissible in evidence in any de novo action at law or equity brought pursuant to this subsection."],[0,"(5) Whenever a person fails to comply with an order issued under paragraph (1), the head of the agency shall file an action for enforcement of such order in the United States district court for a district in which the reprisal was found to have occurred. In any action brought under this paragraph, the court may grant appropriate relief, including injunctive relief, compensatory and exemplary damages, and reasonable attorney fees and costs. The person upon whose behalf an order was issued may also file such an action or join in an action filed by the head of the agency."],[0,"(6) Any person adversely affected or aggrieved by an order issued under paragraph (1) may obtain review of the order's conformance with this subsection, and any regulations issued to carry out this section, in the United States court of appeals for a circuit in which the reprisal is alleged in the order to have occurred. No petition seeking such review may be filed more than 60 days after issuance of the order by the head of the agency. Review shall conform to chapter 7 of title 5. Filing such an appeal shall not act to stay the enforcement of the order of the head of an agency, unless a stay is specifically entered by the court."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/4701?type=usc&year=mostrecent&link-type=html"},"head":"§4701. Contractor employees: protection from reprisal for disclosure of certain information","tname":"Armed Forces","by":{"0":"6","2":"37"}},{"t":"usc","label":"31 U.S.C. § 5323","url":"https://www.law.cornell.edu/uscode/text/31/5323","subs":["(g)(3)"],"stext":{"head":"§5323. Whistleblower incentives and protections","paras":[[0,"(a) Definitions.—In this section:"],[1,"(1) Covered judicial or administrative action.—The term \"covered judicial or administrative action\" means any judicial or administrative action brought by the Secretary of the Treasury (referred to in this section as the \"Secretary\") or the Attorney General under this subchapter, chapter 35 or section 4305 or 4312 of title 50, the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1901 et seq.), or .),1 and for conspiracies to violate the aforementioned provisions that results in monetary sanctions exceeding $1,000,000."],[1,"(2) Monetary sanctions.—The term \"monetary sanctions\", when used with respect to any judicial or administrative action—"],[2,"(A) means any monies, including penalties, disgorgement, and interest, ordered to be paid; and"],[2,"(B) does not include—"],[3,"(i) forfeiture;"],[3,"(ii) restitution; or"],[3,"(iii) any victim compensation payment."],[1,"(3) Original information.—The term \"original information\" means information that—"],[2,"(A) is derived from the independent knowledge or analysis of a whistleblower;"],[2,"(B) is not known to the Secretary or the Attorney General from any other source, unless the whistleblower is the original source of the information; and"],[2,"(C) is not exclusively derived from an allegation made in a judicial or administrative hearing, in a governmental report, hearing, audit, or investigation, or from the news media, unless the whistleblower is a source of the information."],[1,"(4) Related action.—The term \"related action\", when used with respect to any covered judicial or administrative action brought by the Secretary or the Attorney General, means any judicial or administrative action brought by an entity described in any of subclauses (I) through (III) of subsection (g)(4)(D)(i) that is based upon the original information provided by a whistleblower pursuant to subsection (b) that led to the successful enforcement of the covered action."],[1,"(5) Whistleblower.—"],[2,"(A) In general.—The term \"whistleblower\" means any individual who provides, or 2 or more individuals acting jointly who provide, information relating to a violation of this subchapter, chapter 35 or section 4305 or 4312 of title 50, the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1901 et seq.), or .),1 and for conspiracies to violate the aforementioned provisions to the employer of the individual or individuals, including as part of the job duties of the individual or individuals, or to the Secretary or the Attorney General."],[2,"(B) Special rule.—Solely for the purposes of subsection (g)(1), the term \"whistleblower\" includes any individual who takes, or 2 or more individuals acting jointly who take, an action described in subsection (g)(1)(A)."],[0,"(b) Awards.—"],[1,"(1) In general.—In any covered judicial or administrative action, or related action, the Secretary, under regulations prescribed by the Secretary, in consultation with the Attorney General and subject to subsection (c), shall pay an award or awards to 1 or more whistleblowers who voluntarily provided original information to the employer of the individual, the Secretary, or the Attorney General, as applicable, that led to the successful enforcement of the covered judicial or administrative action, or related action, in an aggregate amount equal to—"],[2,"(A) not less than 10 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions; and"],[2,"(B) not more than 30 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions."],[1,"(2) Payment of awards.—"],[2,"(A) In general.—Any amount paid under paragraph (1) shall be paid from the Fund established under paragraph (3)."],[2,"(B) Related actions.—The Secretary may pay awards less than the amount described in paragraph (1)(A) for related actions in which a whistleblower may be paid by another whistleblower award program."],[1,"(3) Source of awards.—"],[2,"(A) In general.—There shall be established in the Treasury of the United States a revolving fund to be known as the Financial Integrity Fund (referred to in this subsection as the \"Fund\")."],[2,"(B) Use of fund.—The Fund shall be available to the Secretary, without further appropriation or fiscal year limitations, only for the payment of awards to whistleblowers as provided in subsection (b)."],[2,"(C) Restrictions on use of fund.—The Fund shall not be available to pay any personnel or administrative expenses."],[1,"(4) Deposits and credits.—"],[2,"(A) In general.—There shall be deposited into or credited to the Fund an amount equal to—"],[3,"(i) any monetary sanction collected by the Secretary or Attorney General in any judicial or administrative action under this title, chapter 35 or section 4305 or 4312 of title 50, or the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1901 et seq.), unless the balance of the Fund at the time the monetary sanction is collected exceeds $300,000,000; and"],[3,"(ii) all income from investments made under paragraph (5)."],[2,"(B) Additional amounts.—If the amounts deposited into or credited to the Fund under subparagraph (A) are not sufficient to satisfy an award made under this subsection, there shall be deposited into or credited to the Fund an amount equal to the unsatisfied portion of the award from any monetary sanction collected by the Secretary of the Treasury or Attorney General in the covered judicial or administrative action on which the award is based."],[2,"(C) Exception.—No amounts to be deposited or transferred into the United States Victims of State Sponsored Terrorism Fund pursuant to the Justice for United States Victims of State Sponsored Terrorism Act (34 U.S.C. 20144) or the Crime Victims Fund pursuant section 1402 of the Victims of Crime Act of 1984 (34 U.S.C. 20101) shall be deposited into or credited to the Fund."],[1,"(5) Investments.—"],[2,"(A) Amounts in fund may be invested.—The Secretary of the Treasury may invest the portion of the Fund that is not required to meet the current needs of the Fund."],[2,"(B) Eligible investments.—Investments shall be made by the Secretary of the Treasury in obligations of the United States or obligations that are guaranteed as to principal and interest by the United States, with maturities suitable to the needs of the Fund as determined by the Secretary."],[2,"(C) Interest and proceeds credited.—The interest on, and the proceeds from the sale or redemption of, any obligations held in the Fund shall be credited to, and form a part of, the Fund."],[0,"(c) Determination of Amount of Award; Denial of Award.—"],[1,"(1) Determination of amount of award.—"],[2,"(A) Discretion.—The determination of the amount of an award made under subsection (b) shall be in the discretion of the Secretary."],[2,"(B) Criteria.—In determining the amount of an award made under subsection (b), the Secretary shall take into consideration—"],[3,"(i) the significance of the information provided by the whistleblower to the success of the covered judicial or administrative action;"],[3,"(ii) the degree of assistance provided by the whistleblower and any legal representative of the whistleblower in a covered judicial or administrative action;"],[3,"(iii) the programmatic interest of the Department of the Treasury in deterring violations of this this 1 subchapter, chapter 35 or section 4305 or 4312 of title 50, and the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1901 et seq.) by making awards to whistleblowers who provide information that lead to the successful enforcement of the covered judicial or administrative action; and"],[3,"(iv) such additional relevant factors as the Secretary, in consultation with the Attorney General, may establish by rule or regulation."],[1,"(2) Denial of award.—No award under subsection (b) may be made—"],[2,"(A) to any whistleblower who is, or was at the time the whistleblower acquired the original information submitted to the Secretary or the Attorney General, as applicable, a member, officer, or employee—"],[3,"(i) of—"],[4,"(I) an appropriate regulatory or banking agency;"],[4,"(II) the Department of the Treasury or the Department of Justice; or"],[4,"(III) a law enforcement agency; and"],[3,"(ii) acting in the normal course of the job duties of the whistleblower;"],[2,"(B) to any whistleblower who is convicted of a criminal violation related to the judicial or administrative action for which the whistleblower otherwise could receive an award under this section; or"],[2,"(C) to any whistleblower who fails to submit information to the Secretary or the Attorney General, as applicable, in such form as the Secretary, in consultation with the Attorney General, may, by rule, require."],[0,"(d) Representation.—"],[1,"(1) Permitted representation.—Any whistleblower who makes a claim for an award under subsection (b) may be represented by counsel."],[1,"(2) Required representation.—"],[2,"(A) In general.—Any whistleblower who anonymously makes a claim for an award under subsection (b) shall be represented by counsel if the whistleblower anonymously submits the information upon which the claim is based."],[2,"(B) Disclosure of identity.—Before the payment of an award, a whistleblower shall disclose the identity of the whistleblower and provide such other information as the Secretary may require, directly or through counsel for the whistleblower."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/5323?type=usc&year=mostrecent&link-type=html"},"head":"§5323. Whistleblower incentives and protections","tname":"Money and Finance","by":{"0":"7","1":"8"}},{"t":"law","label":"National Energy Policy Act, Pub. L. No. 102-486","url":"https://www.govinfo.gov/link/statute/106/2776","by":{"0":"7","1":"7","2":"38"}},{"t":"usc","label":"42 U.S.C. § 5851","url":"https://www.law.cornell.edu/uscode/text/42/5851","subs":["(b)(3)","(a)(1)"],"stext":{"head":"§5851. Employee protection","paras":[[0,"(a) Discrimination against employee"],[0,"(1) No employer may discharge any employee or otherwise discriminate against any employee with respect to his compensation, terms, conditions, or privileges of employment because the employee (or any person acting pursuant to a request of the employee)—"],[1,"(A) notified his employer of an alleged violation of this chapter or the Atomic Energy Act of 1954 (42 U.S.C. 2011 et seq.);"],[1,"(B) refused to engage in any practice made unlawful by this chapter or the Atomic Energy Act of 1954, if the employee has identified the alleged illegality to the employer;"],[1,"(C) testified before Congress or at any Federal or State proceeding regarding any provision (or proposed provision) of this chapter or the Atomic Energy Act of 1954;"],[1,"(D) commenced, caused to be commenced, or is about to commence or cause to be commenced a proceeding under this chapter or the Atomic Energy Act of 1954, as amended, or a proceeding for the administration or enforcement of any requirement imposed under this chapter or the Atomic Energy Act of 1954, as amended;"],[1,"(E) testified or is about to testify in any such proceeding or;"],[1,"(F) assisted or participated or is about to assist or participate in any manner in such a proceeding or in any other manner in such a proceeding or in any other action to carry out the purposes of this chapter or the Atomic Energy Act of 1954, as amended."],[0,"(2) For purposes of this section, the term \"employer\" includes—"],[1,"(A) a licensee of the Commission or of an agreement State under section 274 of the Atomic Energy Act of 1954 (42 U.S.C. 2021);"],[1,"(B) an applicant for a license from the Commission or such an agreement State;"],[1,"(C) a contractor or subcontractor of such a licensee or applicant;"],[1,"(D) a contractor or subcontractor of the Department of Energy that is indemnified by the Department under section 170 d. of the Atomic Energy Act of 1954 (42 U.S.C. 2210(d)), but such term shall not include any contractor or subcontractor covered by Executive Order No. 12344;"],[1,"(E) a contractor or subcontractor of the Commission;"],[1,"(F) the Commission; and"],[1,"(G) the Department of Energy."],[0,"(b) Complaint, filing and notification"],[0,"(1) Any employee who believes that he has been discharged or otherwise discriminated against by any person in violation of subsection (a) may, within 180 days after such violation occurs, file (or have any person file on his behalf) a complaint with the Secretary of Labor (in this section referred to as the \"Secretary\") alleging such discharge or discrimination. Upon receipt of such a complaint, the Secretary shall notify the person named in the complaint of the filing of the complaint, the Commission, and the Department of Energy."],[0,"(2)(A) Upon receipt of a complaint filed under paragraph (1), the Secretary shall conduct an investigation of the violation alleged in the complaint. Within thirty days of the receipt of such complaint, the Secretary shall complete such investigation and shall notify in writing the complainant (and any person acting in his behalf) and the person alleged to have committed such violation of the results of the investigation conducted pursuant to this subparagraph. Within ninety days of the receipt of such complaint the Secretary shall, unless the proceeding on the complaint is terminated by the Secretary on the basis of a settlement entered into by the Secretary and the person alleged to have committed such violation, issue an order either providing the relief prescribed by subparagraph (B) or denying the complaint. An order of the Secretary shall be made on the record after notice and opportunity for public hearing. Upon the conclusion of such hearing and the issuance of a recommended decision that the complaint has merit, the Secretary shall issue a preliminary order providing the relief prescribed in subparagraph (B), but may not order compensatory damages pending a final order. The Secretary may not enter into a settlement terminating a proceeding on a complaint without the participation and consent of the complainant."],[0,"(B) If, in response to a complaint filed under paragraph (1), the Secretary determines that a violation of subsection (a) has occurred, the Secretary shall order the person who committed such violation to (i) take affirmative action to abate the violation, and (ii) reinstate the complainant to his former position together with the compensation (including back pay), terms, conditions, and privileges of his employment, and the Secretary may order such person to provide compensatory damages to the complainant. If an order is issued under this paragraph, the Secretary, at the request of the complainant shall assess against the person against whom the order is issued a sum equal to the aggregate amount of all costs and expenses (including attorneys' and expert witness fees) reasonably incurred, as determined by the Secretary, by the complainant for, or in connection with, the bringing of the complaint upon which the order was issued."],[0,"(3)(A) The Secretary shall dismiss a complaint filed under paragraph (1), and shall not conduct the investigation required under paragraph (2), unless the complainant has made a prima facie showing that any behavior described in subparagraphs (A) through (F) of subsection (a)(1) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(B) Notwithstanding a finding by the Secretary that the complainant has made the showing required by subparagraph (A), no investigation required under paragraph (2) shall be conducted if the employer demonstrates, by clear and convincing evidence, that it would have taken the same unfavorable personnel action in the absence of such behavior."],[0,"(C) The Secretary may determine that a violation of subsection (a) has occurred only if the complainant has demonstrated that any behavior described in subparagraphs (A) through (F) of subsection (a)(1) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[0,"(D) Relief may not be ordered under paragraph (2) if the employer demonstrates by clear and convincing evidence that it would have taken the same unfavorable personnel action in the absence of such behavior."],[0,"(4) If the Secretary has not issued a final decision within 1 year after the filing of a complaint under paragraph (1), and there is no showing that such delay is due to the bad faith of the person seeking relief under this paragraph, such person may bring an action at law or equity for de novo review in the appropriate district court of the United States, which shall have jurisdiction over such an action without regard to the amount in controversy."],[0,"(c) Review"],[0,"(1) Any person adversely affected or aggrieved by an order issued under subsection (b) may obtain review of the order in the United States court of appeals for the circuit in which the violation, with respect to which the order was issued, allegedly occurred. The petition for review must be filed within sixty days from the issuance of the Secretary's order. Review shall conform to chapter 7 of title 5. The commencement of proceedings under this subparagraph shall not, unless ordered by the court, operate as a stay of the Secretary's order."],[0,"(2) An order of the Secretary with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in any criminal or other civil proceeding."],[0,"(d) Jurisdiction"],[0,"Whenever a person has failed to comply with an order issued under subsection (b)(2), the Secretary may file a civil action in the United States district court for the district in which the violation was found to occur to enforce such order. In actions brought under this subsection, the district courts shall have jurisdiction to grant all appropriate relief including, but not limited to, injunctive relief, compensatory, and exemplary damages."],[0,"(e) Commencement of action"],[0,"(1) Any person on whose behalf an order was issued under paragraph (2) of subsection (b) may commence a civil action against the person to whom such order was issued to require compliance with such order. The appropriate United States district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce such order."],[0,"(2) The court, in issuing any final order under this subsection, may award costs of litigation (including reasonable attorney and expert witness fees) to any party whenever the court determines such award is appropriate."],[0,"(f) Enforcement"],[0,"Any nondiscretionary duty imposed by this section shall be enforceable in a mandamus proceeding brought under section 1361 of title 28."],[0,"(g) Deliberate violations"],[0,"Subsection (a) shall not apply with respect to any employee who, acting without direction from his or her employer (or the employer's agent), deliberately causes a violation of any requirement of this chapter or of the Atomic Energy Act of 1954, as amended [42 U.S.C. 2011 et seq.]."],[0,"(h) Nonpreemption"],[0,"This section may not be construed to expand, diminish, or otherwise affect any right otherwise available to an employee under Federal or State law to redress the employee's discharge or other discriminatory action taken by the employer against the employee."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/5851?type=usc&year=mostrecent&link-type=html"},"head":"§5851. Employee protection","tname":"The Public Health and Welfare","by":{"0":"7","1":"7","2":"4, 4"}},{"t":"law","label":"Patient Protection & Affordable Care Act, Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 218c","url":"https://www.law.cornell.edu/uscode/text/29/218c","subs":["(b)(1)"],"by":{"0":"7, 33"}},{"t":"law","label":"Pub. L. No. 107-355","url":"https://www.govinfo.gov/link/plaw/107/public/355","by":{"0":"7"}},{"t":"usc","label":"49 U.S.C. § 60129","url":"https://www.law.cornell.edu/uscode/text/49/60129","subs":["(b)(2)(B)"],"by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"0":"2-4, 8, 15-19, 21, 23-29, 31, 33-34, 36-40","1":"1","2":"29","3":"1-4, 6, 9-17, 19, 21"}},{"t":"usc","label":"18 U.S.C. § 1513","url":"https://www.law.cornell.edu/uscode/text/18/1513","subs":["(e)","(a)","(b)"],"by":{"0":"24","2":"28, 29, 29"}},{"t":"usc","label":"18 U.S.C. § 1514A","url":"https://www.law.cornell.edu/uscode/text/18/1514A","subs":["(a)","(b)(2)","(b)(2)(C)","(b)","(b)(1)(A)","(b)(1)(B)","(b)(2)(A)","(b)(2)(D)","(b)(1)","(a)(1)","(c)(1)","(c)(2)(A)"],"stext":{"head":"§1514A. Civil action to protect against retaliation in fraud cases","paras":[[0,"(a) Whistleblower Protection for Employees of Publicly Traded Companies.—No company with a class of securities registered under section 12 of the Securities Exchange Act of 1934 (15 U.S.C. 78l), or that is required to file reports under section 15(d) of the Securities Exchange Act of 1934 (15 U.S.C. 78o(d)) including any subsidiary or affiliate whose financial information is included in the consolidated financial statements of such company, or nationally recognized statistical rating organization (as defined in section 3(a) of the Securities Exchange Act of 1934 (15 U.S.C. 78c),1 or any officer, employee, contractor, subcontractor, or agent of such company or nationally recognized statistical rating organization, may discharge, demote, suspend, threaten, harass, or in any other manner discriminate against an employee in the terms and conditions of employment because of any lawful act done by the employee—"],[1,"(1) to provide information, cause information to be provided, or otherwise assist in an investigation regarding any conduct which the employee reasonably believes constitutes a violation of section 1341, 1343, 1344, or 1348, any rule or regulation of the Securities and Exchange Commission, or any provision of Federal law relating to fraud against shareholders, when the information or assistance is provided to or the investigation is conducted by—"],[2,"(A) a Federal regulatory or law enforcement agency;"],[2,"(B) any Member of Congress or any committee of Congress; or"],[2,"(C) a person with supervisory authority over the employee (or such other person working for the employer who has the authority to investigate, discover, or terminate misconduct); or"],[1,"(2) to file, cause to be filed, testify, participate in, or otherwise assist in a proceeding filed or about to be filed (with any knowledge of the employer) relating to an alleged violation of section 1341, 1343, 1344, or 1348, any rule or regulation of the Securities and Exchange Commission, or any provision of Federal law relating to fraud against shareholders."],[0,"(b) Enforcement Action.—"],[1,"(1) In general.—A person who alleges discharge or other discrimination by any person in violation of subsection (a) may seek relief under subsection (c), by—"],[2,"(A) filing a complaint with the Secretary of Labor; or"],[2,"(B) if the Secretary has not issued a final decision within 180 days of the filing of the complaint and there is no showing that such delay is due to the bad faith of the claimant, bringing an action at law or equity for de novo review in the appropriate district court of the United States, which shall have jurisdiction over such an action without regard to the amount in controversy."],[1,"(2) Procedure.—"],[2,"(A) In general.—An action under paragraph (1)(A) shall be governed under the rules and procedures set forth in section 42121(b) of title 49, United States Code."],[2,"(B) Exception.—Notification made under section 42121(b)(1) of title 49, United States Code, shall be made to the person named in the complaint and to the employer."],[2,"(C) Burdens of proof.—An action brought under paragraph (1)(B) shall be governed by the legal burdens of proof set forth in section 42121(b) of title 49, United States Code."],[2,"(D) Statute of limitations.—An action under paragraph (1) shall be commenced not later than 180 days after the date on which the violation occurs, or after the date on which the employee became aware of the violation."],[2,"(E) Jury trial.—A party to an action brought under paragraph (1)(B) shall be entitled to trial by jury."],[0,"(c) Remedies.—"],[1,"(1) In general.—An employee prevailing in any action under subsection (b)(1) shall be entitled to all relief necessary to make the employee whole."],[1,"(2) Compensatory damages.—Relief for any action under paragraph (1) shall include—"],[2,"(A) reinstatement with the same seniority status that the employee would have had, but for the discrimination;"],[2,"(B) the amount of back pay, with interest; and"],[2,"(C) compensation for any special damages sustained as a result of the discrimination, including litigation costs, expert witness fees, and reasonable attorney fees."],[0,"(d) Rights Retained by Employee.—Nothing in this section shall be deemed to diminish the rights, privileges, or remedies of any employee under any Federal or State law, or under any collective bargaining agreement."],[0,"(e) Nonenforceability of Certain Provisions Waiving Rights and Remedies or Requiring Arbitration of Disputes.—"],[1,"(1) Waiver of rights and remedies.—The rights and remedies provided for in this section may not be waived by any agreement, policy form, or condition of employment, including by a predispute arbitration agreement."],[1,"(2) Predispute arbitration agreements.—No predispute arbitration agreement shall be valid or enforceable, if the agreement requires arbitration of a dispute arising under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1514A?type=usc&year=mostrecent&link-type=html"},"op":17,"sum":"Explaining that an action brought in federal court “shall be governed by the legal burdens of proof set forth in section 42121(b)”.","sumSrc":"opinion","head":"§1514A. Civil action to protect against retaliation in fraud cases","tname":"Crimes and Criminal Procedure","by":{"0":"1, 19, 21, 24, 28, 35, 2, 4, 16, 17, 21, 28, 34, 35, 7, 2, 8, 17, 21, 32","1":"2, 2, 2, 2, 2, 2, 2, 2","2":"22, 23, 31, 22, 23, 31, 22, 23, 31, 22, 23, 31","3":"21, 16, 14, 15, 1, 2, 3, 5, 15, 11"}},{"t":"law","label":"Pub. L. No. 116-25","url":"https://www.govinfo.gov/link/plaw/116/public/25","by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 7623","url":"https://www.law.cornell.edu/uscode/text/26/7623","subs":["(d)(2)(B)(i)"],"by":{"0":"7"}},{"t":"usc","label":"38 U.S.C. § 4301","url":"https://www.law.cornell.edu/uscode/text/38/4301","by":{"0":"24"}},{"t":"usc","label":"38 U.S.C. § 4311","url":"https://www.law.cornell.edu/uscode/text/38/4311","subs":["(c)(2)"],"by":{"0":"24"}},{"t":"law","label":"Wendell H. Ford Aviation Investment and Reform Act, Pub. L. No. 106-181","url":"https://www.govinfo.gov/link/plaw/106/public/181","by":{"0":"1, 7","2":"38"}},{"t":"usc","label":"49 U.S.C. § 42121","url":"https://www.law.cornell.edu/uscode/text/49/42121","subs":["(b)","(b)(2)(B)","(b)(2)(B)(i)","(b)(2)(B)(ii)","(b)(2)(B)(iii)","(b)(2)(B)(iv)","(2000)","(b)(1)","(b)(2)(A)","(b)(3)(A)","(b)(4)","(b)(3)(B)"],"stext":{"head":"§42121. Protection of employees providing air safety information","paras":[[0,"(a) Prohibited Discrimination.—A holder of a certificate under section 44704 or 44705 of this title, or a contractor, subcontractor, or supplier of such holder, may not discharge an employee or otherwise discriminate against an employee with respect to compensation, terms, conditions, or privileges of employment because the employee (or any person acting pursuant to a request of the employee)—"],[1,"(1) provided, caused to be provided, or is about to provide (with any knowledge of the employer) or cause to be provided to the employer or Federal Government information relating to any violation or alleged violation of any order, regulation, or standard of the Federal Aviation Administration or any other provision of Federal law relating to aviation safety under this subtitle or any other law of the United States;"],[1,"(2) has filed, caused to be filed, or is about to file (with any knowledge of the employer) or cause to be filed a proceeding relating to any violation or alleged violation of any order, regulation, or standard of the Federal Aviation Administration or any other provision of Federal law relating to aviation safety under this subtitle or any other law of the United States;"],[1,"(3) testified or is about to testify in such a proceeding; or"],[1,"(4) assisted or participated or is about to assist or participate in such a proceeding."],[0,"(b) Department of Labor and Federal Aviation Administration Complaint Procedure.—"],[1,"(1) Filing and notification.—A person who believes that he or she has been discharged or otherwise discriminated against by any person in violation of subsection (a) may, not later than 90 days after the date on which such violation occurs, file (or have any person file on his or her behalf) a complaint with the Secretary of Labor alleging such discharge or discrimination. Upon receipt of such a complaint, the Secretary of Labor shall notify, in writing, the person named in the complaint and the Administrator of the Federal Aviation Administration of the filing of the complaint, of the allegations contained in the complaint, of the substance of evidence supporting the complaint, and of the opportunities that will be afforded to such person under paragraph (2)."],[1,"(2) Investigation; preliminary order.—"],[2,"(A) In general.—Not later than 60 days after the date of receipt of a complaint filed under paragraph (1) and after affording the person named in the complaint an opportunity to submit to the Secretary of Labor a written response to the complaint and an opportunity to meet with a representative of the Secretary to present statements from witnesses, the Secretary of Labor shall conduct an investigation and determine whether there is reasonable cause to believe that the complaint has merit and notify, in writing, the complainant and the person alleged to have committed a violation of subsection (a) of the Secretary's findings. If the Secretary of Labor concludes that there is a reasonable cause to believe that a violation of subsection (a) has occurred, the Secretary shall accompany the Secretary's findings with a preliminary order providing the relief prescribed by paragraph (3)(B). Not later than 30 days after the date of notification of findings under this paragraph, either the person alleged to have committed the violation or the complainant may file objections to the findings or preliminary order, or both, and request a hearing on the record. The filing of such objections shall not operate to stay any reinstatement remedy contained in the preliminary order. Such hearings shall be conducted expeditiously. If a hearing is not requested in such 30-day period, the preliminary order shall be deemed a final order that is not subject to judicial review."],[2,"(B) Requirements.—"],[3,"(i) Required showing by complainant.—The Secretary of Labor shall dismiss a complaint filed under this subsection and shall not conduct an investigation otherwise required under subparagraph (A) unless the complainant makes a prima facie showing that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[3,"(ii) Showing by employer.—Notwithstanding a finding by the Secretary that the complainant has made the showing required under clause (i), no investigation otherwise required under subparagraph (A) shall be conducted if the employer demonstrates, by clear and convincing evidence, that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[3,"(iii) Criteria for determination by secretary.—The Secretary may determine that a violation of subsection (a) has occurred only if the complainant demonstrates that any behavior described in paragraphs (1) through (4) of subsection (a) was a contributing factor in the unfavorable personnel action alleged in the complaint."],[3,"(iv) Prohibition.—Relief may not be ordered under subparagraph (A) if the employer demonstrates by clear and convincing evidence that the employer would have taken the same unfavorable personnel action in the absence of that behavior."],[1,"(3) Final order.—"],[2,"(A) Deadline for issuance; settlement agreements.—Not later than 120 days after the date of conclusion of a hearing under paragraph (2), the Secretary of Labor shall issue a final order providing the relief prescribed by this paragraph or denying the complaint. At any time before issuance of a final order, a proceeding under this subsection may be terminated on the basis of a settlement agreement entered into by the Secretary of Labor, the complainant, and the person alleged to have committed the violation."],[2,"(B) Remedy.—If, in response to a complaint filed under paragraph (1), the Secretary of Labor determines that a violation of subsection (a) has occurred, the Secretary of Labor shall order the person who committed such violation to—"],[3,"(i) take affirmative action to abate the violation;"],[3,"(ii) reinstate the complainant to his or her former position together with the compensation (including back pay) and restore the terms, conditions, and privileges associated with his or her employment; and"],[3,"(iii) provide compensatory damages to the complainant."],[2,"If such an order is issued under this paragraph, the Secretary of Labor, at the request of the complainant, shall assess against the person against whom the order is issued a sum equal to the aggregate amount of all costs and expenses (including attorneys' and expert witness fees) reasonably incurred, as determined by the Secretary of Labor, by the complainant for, or in connection with, the bringing the complaint upon which the order was issued."],[2,"(C) Frivolous complaints.—If the Secretary of Labor finds that a complaint under paragraph (1) is frivolous or has been brought in bad faith, the Secretary of Labor may award to the prevailing employer a reasonable attorney's fee not exceeding $1,000."],[1,"(4) Review.—"],[2,"(A) Appeal to court of appeals.—Any person adversely affected or aggrieved by an order issued under paragraph (3) may obtain review of the order in the United States Court of Appeals for the circuit in which the violation, with respect to which the order was issued, allegedly occurred or the circuit in which the complainant resided on the date of such violation. The petition for review must be filed not later than 60 days after the date of the issuance of the final order of the Secretary of Labor. Review shall conform to chapter 7 of title 5, United States Code. The commencement of proceedings under this subparagraph shall not, unless ordered by the court, operate as a stay of the order."],[2,"(B) Limitation on collateral attack.—An order of the Secretary of Labor with respect to which review could have been obtained under subparagraph (A) shall not be subject to judicial review in any criminal or other civil proceeding."],[1,"(5) Enforcement of order.—Whenever any person has failed to comply with an order issued under paragraph (3), the Secretary of Labor and the Administrator of the Federal Aviation Administration shall consult with each other to determine the most appropriate action to be taken, in which—"],[2,"(A) the Secretary of Labor may file a civil action in the United States district court for the district in which the violation was found to occur to enforce such order, for which, in actions brought under this paragraph, the district courts shall have jurisdiction to grant all appropriate relief including, injunctive relief and compensatory damages; and"],[2,"(B) the Administrator of the Federal Aviation Administration may assess a civil penalty pursuant to section 46301."],[1,"(6) Enforcement of order by parties.—"],[2,"(A) Commencement of action.—A person on whose behalf an order was issued under paragraph (3) may commence a civil action against the person to whom such order was issued to require compliance with such order. The appropriate United States district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce such order."],[2,"(B) Attorney fees.—The court, in issuing any final order under this paragraph, may award costs of litigation (including reasonable attorney and expert witness fees) to any party whenever the court determines such award is appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/42121?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§42121. Protection of employees providing air safety information","tname":"Transportation","by":{"0":"1-2, 8, 17-18, 21-24, 34, 7, 32, 2-3, 8, 18, 22-23, 27, 2, 8, 18, 22, 25, 27, 36, 2-3, 8, 18, 22-23, 27, 2, 8, 18, 22, 25, 27, 36","1":"2, 19, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6, 2, 6","2":"37, 37, 37, 37","3":"1-3, 5, 6, 8, 10-11, 14-16, 20, 1-3, 5, 6, 8, 10-11, 14-16, 20, 15"}},{"t":"law","label":"Pub. L. No. 101-12","url":"https://www.govinfo.gov/link/statute/103/16","by":{"0":"3-6, 8, 19-20, 27-33, 39","2":"3, 36"}},{"t":"usc","label":"5 U.S.C. § 1221","url":"https://www.law.cornell.edu/uscode/text/5/1221","subs":["(e)","(e)(1)","(e)(1)(B)","(e)(2)","(h)(2)(2006)","(c)(1)"],"stext":{"head":"§1221. Individual right of action in certain reprisal cases","paras":[[0,"(a) Subject to the provisions of subsection (b) of this section and subsection 1214(a)(3), an employee, former employee, or applicant for employment may, with respect to any personnel action taken, or proposed to be taken, against such employee, former employee, or applicant for employment, as a result of a prohibited personnel practice described in section 2302(b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D), seek corrective action from the Merit Systems Protection Board."],[0,"(b) This section may not be construed to prohibit any employee, former employee, or applicant for employment from seeking corrective action from the Merit Systems Protection Board before seeking corrective action from the Special Counsel, if such employee, former employee, or applicant for employment has the right to appeal directly to the Board under any law, rule, or regulation."],[0,"(c)(1) Any employee, former employee, or applicant for employment seeking corrective action under subsection (a) may request that the Board order a stay of the personnel action involved."],[0,"(2) Any stay requested under paragraph (1) shall be granted within 10 calendar days (excluding Saturdays, Sundays, and legal holidays) after the date the request is made, if the Board determines that such a stay would be appropriate."],[0,"(3)(A) The Board shall allow any agency which would be subject to a stay under this subsection to comment to the Board on such stay request."],[0,"(B) Except as provided in subparagraph (C), a stay granted under this subsection shall remain in effect for such period as the Board determines to be appropriate."],[0,"(C) The Board may modify or dissolve a stay under this subsection at any time, if the Board determines that such a modification or dissolution is appropriate."],[0,"(d)(1) At the request of an employee, former employee, or applicant for employment seeking corrective action under subsection (a), the Board shall issue a subpoena for the attendance and testimony of any person or the production of documentary or other evidence from any person if the Board finds that the testimony or production requested is not unduly burdensome and appears reasonably calculated to lead to the discovery of admissible evidence."],[0,"(2) A subpoena under this subsection may be issued, and shall be enforced, in the same manner as applies in the case of subpoenas under section 1204."],[0,"(e)(1) Subject to the provisions of paragraph (2), in any case involving an alleged prohibited personnel practice as described under section 2302(b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D), the Board shall order such corrective action as the Board considers appropriate if the employee, former employee, or applicant for employment has demonstrated that a disclosure or protected activity described under section 2302(b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D) was a contributing factor in the personnel action which was taken or is to be taken against such employee, former employee, or applicant. The employee may demonstrate that the disclosure or protected activity was a contributing factor in the personnel action through circumstantial evidence, such as evidence that—"],[1,"(A) the official taking the personnel action knew of the disclosure or protected activity; and"],[1,"(B) the personnel action occurred within a period of time such that a reasonable person could conclude that the disclosure or protected activity was a contributing factor in the personnel action."],[0,"(2) Corrective action under paragraph (1) may not be ordered if, after a finding that a protected disclosure was a contributing factor, the agency demonstrates by clear and convincing evidence that it would have taken the same personnel action in the absence of such disclosure."],[0,"(f)(1) A final order or decision shall be rendered by the Board as soon as practicable after the commencement of any proceeding under this section."],[0,"(2) A decision to terminate an investigation under subchapter II may not be considered in any action or other proceeding under this section."],[0,"(3) If, based on evidence presented to it under this section, the Merit Systems Protection Board determines that there is reason to believe that a current employee may have committed a prohibited personnel practice, the Board shall refer the matter to the Special Counsel to investigate and take appropriate action under section 1215."],[0,"(g)(1)(A) If the Board orders corrective action under this section, such corrective action may include—"],[1,"(i) that the individual be placed, as nearly as possible, in the position the individual would have been in had the prohibited personnel practice not occurred; and"],[1,"(ii) back pay and related benefits, medical costs incurred, travel expenses, any other reasonable and foreseeable consequential damages, and compensatory damages (including interest, reasonable expert witness fees, and costs)."],[0,"(B) Corrective action shall include attorney's fees and costs as provided for under paragraphs (2) and (3)."],[0,"(2) If an employee, former employee, or applicant for employment is the prevailing party before the Merit Systems Protection Board, and the decision is based on a finding of a prohibited personnel practice, the agency involved shall be liable to the employee, former employee, or applicant for reasonable attorney's fees and any other reasonable costs incurred."],[0,"(3) If an employee, former emloyee,1 or applicant for employment is the prevailing party in an appeal from the Merit Systems Protection Board, the agency involved shall be liable to the employee, former employee, or applicant for reasonable attorney's fees and any other reasonable costs incurred, regardless of the basis of the decision."],[0,"(4) Any corrective action ordered under this section to correct a prohibited personnel practice may include fees, costs, or damages reasonably incurred due to an agency investigation of the employee, if such investigation was commenced, expanded, or extended in retaliation for the disclosure or protected activity that formed the basis of the corrective action."],[0,"(h)(1) An employee, former employee, or applicant for employment adversely affected or aggrieved by a final order or decision of the Board under this section may obtain judicial review of the order or decision."],[0,"(2) A petition for review under this subsection shall be filed with such court, and within such time, as provided for under section 7703(b)."],[0,"(i) Subsections (a) through (h) shall apply in any proceeding brought under section 7513(d) if, or to the extent that, a prohibited personnel practice as defined in section 2302(b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D) is alleged."],[0,"(j) In determining the appealability of any case involving an allegation made by an individual under the provisions of this chapter, neither the status of an individual under any retirement system established under a Federal statute nor any election made by such individual under any such system may be taken into account."],[0,"(k) If the Board grants a stay under subsection (c) and the employee who is the subject of the action is in probationary status, the head of the agency employing the employee shall give priority to a request for a transfer submitted by the employee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1221?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1221. Individual right of action in certain reprisal cases","tname":"Government Organization and Employees","by":{"0":"28, 5, 5, 29, 27, 27","1":"2, 6, 2, 6, 6, 19, 6, 19, 6, 19, 6, 19, 6, 19","2":"44, 44, 44"}},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","subs":["(b)(8)","(a)(2)","(b)(8)(1988)","(b)(9)(1988)","(b)(1)"],"stext":{"head":"§2302. Prohibited personnel practices","paras":[[0,"(a)(1) For the purpose of this title, \"prohibited personnel practice\" means any action described in subsection (b)."],[0,"(2) For the purpose of this section—"],[1,"(A) \"personnel action\" means—"],[2,"(i) an appointment;"],[2,"(ii) a promotion;"],[2,"(iii) an action under chapter 75 of this title or other disciplinary or corrective action;"],[2,"(iv) a detail, transfer, or reassignment;"],[2,"(v) a reinstatement;"],[2,"(vi) a restoration;"],[2,"(vii) a reemployment;"],[2,"(viii) a performance evaluation under chapter 43 of this title or under title 38;"],[2,"(ix) a decision concerning pay, benefits, or awards, or concerning education or training if the education or training may reasonably be expected to lead to an appointment, promotion, performance evaluation, or other action described in this subparagraph;"],[2,"(x) a decision to order psychiatric testing or examination;"],[2,"(xi) the implementation or enforcement of any nondisclosure policy, form, or agreement; and"],[2,"(xii) any other significant change in duties, responsibilities, or working conditions;"],[1,"with respect to an employee in, or applicant for, a covered position in an agency, and in the case of an alleged prohibited personnel practice described in subsection (b)(8), an employee or applicant for employment in a Government corporation as defined in section 9101 of title 31;"],[1,"(B) \"covered position\" means, with respect to any personnel action, any position in the competitive service, a career appointee position in the Senior Executive Service, or a position in the excepted service, but does not include any position which is, prior to the personnel action—"],[2,"(i) excepted from the competitive service because of its confidential, policy-determining, policy-making, or policy-advocating character; or"],[2,"(ii) excluded from the coverage of this section by the President based on a determination by the President that it is necessary and warranted by conditions of good administration;"],[1,"(C) \"agency\" means an Executive agency and the Government Publishing Office, but does not include—"],[2,"(i) a Government corporation, except in the case of an alleged prohibited personnel practice described under subsection (b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D);"],[2,"(ii)(I) the Federal Bureau of Investigation, the Central Intelligence Agency, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, the Office of the Director of National Intelligence, and the National Reconnaissance Office; and"],[2,"(II) as determined by the President, any executive agency or unit thereof the principal function of which is the conduct of foreign intelligence or counterintelligence activities, provided that the determination be made prior to a personnel action; or"],[2,"(iii) the Government Accountability Office; and"],[1,"(D) \"disclosure\" means a formal or informal communication or transmission, but does not include a communication concerning policy decisions that lawfully exercise discretionary authority unless the employee or applicant providing the disclosure reasonably believes that the disclosure evidences—"],[2,"(i) any violation of any law, rule, or regulation; or"],[2,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety."],[0,"(b) Any employee who has authority to take, direct others to take, recommend, or approve any personnel action, shall not, with respect to such authority—"],[1,"(1) discriminate for or against any employee or applicant for employment—"],[2,"(A) on the basis of race, color, religion, sex, or national origin, as prohibited under section 717 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16);"],[2,"(B) on the basis of age, as prohibited under sections 12 and 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 631, 633a);"],[2,"(C) on the basis of sex, as prohibited under section 6(d) of the Fair Labor Standards Act of 1938 (29 U.S.C. 206(d));"],[2,"(D) on the basis of handicapping condition, as prohibited under section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791); or"],[2,"(E) on the basis of marital status or political affiliation, as prohibited under any law, rule, or regulation;"],[1,"(2) solicit or consider any recommendation or statement, oral or written, with respect to any individual who requests or is under consideration for any personnel action unless such recommendation or statement is based on the personal knowledge or records of the person furnishing it and consists of—"],[2,"(A) an evaluation of the work performance, ability, aptitude, or general qualifications of such individual; or"],[2,"(B) an evaluation of the character, loyalty, or suitability of such individual;"],[1,"(3) coerce the political activity of any person (including the providing of any political contribution or service), or take any action against any employee or applicant for employment as a reprisal for the refusal of any person to engage in such political activity;"],[1,"(4) deceive or willfully obstruct any person with respect to such person's right to compete for employment;"],[1,"(5) influence any person to withdraw from competition for any position for the purpose of improving or injuring the prospects of any other person for employment;"],[1,"(6) grant any preference or advantage not authorized by law, rule, or regulation to any employee or applicant for employment (including defining the scope or manner of competition or the requirements for any position) for the purpose of improving or injuring the prospects of any particular person for employment;"],[1,"(7) appoint, employ, promote, advance, or advocate for appointment, employment, promotion, or advancement, in or to a civilian position any individual who is a relative (as defined in section 3110(a)(3) of this title) of such employee if such position is in the agency in which such employee is serving as a public official (as defined in section 3110(a)(2) of this title) or over which such employee exercises jurisdiction or control as such an official;"],[1,"(8) take or fail to take, or threaten to take or fail to take, a personnel action with respect to any employee or applicant for employment because of—"],[2,"(A) any disclosure of information by an employee or applicant which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety,"],[2,"if such disclosure is not specifically prohibited by law and if such information is not specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs;"],[2,"(B) any disclosure to the Special Counsel, or to the Inspector General of an agency or another employee designated by the head of the agency to receive such disclosures, of information which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation (other than a violation of this section) of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety; or"],[2,"(C) any disclosure to Congress (including any committee of Congress) by any employee of an agency or applicant for employment at an agency of information described in subparagraph (B) that is—"],[3,"(i) not classified; or"],[3,"(ii) if classified—"],[4,"(I) has been classified by the head of an agency that is not an element of the intelligence community (as defined by section 3 of the National Security Act of 1947 (50 U.S.C. 3003)); and"],[4,"(II) does not reveal intelligence sources and methods.1"],[1,"(9) take or fail to take, or threaten to take or fail to take, any personnel action against any employee or applicant for employment because of—"],[2,"(A) the exercise of any appeal, complaint, or grievance right granted by any law, rule, or regulation—"],[3,"(i) with regard to remedying a violation of paragraph (8); or"],[3,"(ii) other than with regard to remedying a violation of paragraph (8);"],[2,"(B) testifying for or otherwise lawfully assisting any individual in the exercise of any right referred to in subparagraph (A)(i) or (ii);"],[2,"(C) cooperating with or disclosing information to the Inspector General (or any other component responsible for internal investigation or review) of an agency, or the Special Counsel, in accordance with applicable provisions of law; or"],[2,"(D) refusing to obey an order that would require the individual to violate a law, rule, or regulation;"],[1,"(10) discriminate for or against any employee or applicant for employment on the basis of conduct which does not adversely affect the performance of the employee or applicant or the performance of others; except that nothing in this paragraph shall prohibit an agency from taking into account in determining suitability or fitness any conviction of the employee or applicant for any crime under the laws of any State, of the District of Columbia, or of the United States;"],[1,"(11)(A) knowingly take, recommend, or approve any personnel action if the taking of such action would violate a veterans' preference requirement; or"],[1,"(B) knowingly fail to take, recommend, or approve any personnel action if the failure to take such action would violate a veterans' preference requirement;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/2302?type=usc&year=mostrecent&link-type=html"},"head":"§2302. Prohibited personnel practices","tname":"Government Organization and Employees","by":{"0":"28","1":"3, 3, 4, 4, 19","2":"44, 44"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)(1)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"25","2":"22, 23, 31"}},{"t":"reg","label":"5 C.F.R. § 1209.4","url":"https://www.ecfr.gov/current/title-5/section-1209.4","subs":["(d)"],"by":{"0":"31"}},{"t":"reg","label":"17 C.F.R. § 242.501","url":"https://www.ecfr.gov/current/title-17/section-242.501","by":{"0":"9"}},{"t":"reg","label":"29 C.F.R. § 1978.104","url":"https://www.ecfr.gov/current/title-29/section-1978.104","subs":["(e)(3)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1979.104","url":"https://www.ecfr.gov/current/title-29/section-1979.104","subs":["(b)(2)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1980.104","url":"https://www.ecfr.gov/current/title-29/section-1980.104","subs":["(e)(3)"],"by":{"0":"32","2":"46"}},{"t":"reg","label":"29 C.F.R. § 1981.104","url":"https://www.ecfr.gov/current/title-29/section-1981.104","subs":["(b)(2)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1982.104","url":"https://www.ecfr.gov/current/title-29/section-1982.104","subs":["(e)(3)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1983.104","url":"https://www.ecfr.gov/current/title-29/section-1983.104","subs":["(e)(3)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1984.104","url":"https://www.ecfr.gov/current/title-29/section-1984.104","subs":["(e)(3)"],"by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 1985.104","url":"https://www.ecfr.gov/current/title-29/section-1985.104","subs":["(e)(3)"],"by":{"0":"33"}},{"t":"reg","label":"29 C.F.R. § 1986.104","url":"https://www.ecfr.gov/current/title-29/section-1986.104","subs":["(e)(3)"],"by":{"0":"33"}},{"t":"reg","label":"29 C.F.R. § 1987.104","url":"https://www.ecfr.gov/current/title-29/section-1987.104","subs":["(e)(3)"],"by":{"0":"33"}},{"t":"reg","label":"29 C.F.R. § 1988.104","url":"https://www.ecfr.gov/current/title-29/section-1988.104","subs":["(e)(3)"],"by":{"0":"33"}},{"t":"reg","label":"48 C.F.R. § 3.907-6","url":"https://www.ecfr.gov/current/title-48/section-3.907-6","subs":["(a)(1)"],"by":{"0":"33"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"op":1,"ar":2,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"1":"25","2":"37, 40"}},{"t":"case","label":"Beatty v. Celadon Trucking Servs.","cite":"2017 WL 6572143","y":2017,"court":"ARB Dec. 8","by":{"1":"33"}},{"t":"case","label":"Brough v. BNSF Ry.","cite":"2019 WL 3293916","y":2019,"court":"ARB June 12","by":{"1":"33"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Caddell v. DOJ","cite":"61 M.S.P.R. 670","y":1994,"url":"https://www.courtlistener.com/c/M.S.P.R./61/670/","by":{"1":"20"}},{"t":"case","label":"Carr v. SSA","cite":"185 F.3d 1318","y":1999,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/185/1318/","sum":"Explaining that questions of retaliatory motive are considered as part of employer’s defense.","sumSrc":"brief:1","by":{"1":"20"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"29","2":"43"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"8","2":"3, 17, 18"}},{"t":"case","label":"Gerlach v. FTC","cite":"8 M.S.P.B. 599","y":1981,"url":"https://www.courtlistener.com/c/M.S.P.B./8/599/","by":{"1":"4"}},{"t":"case","label":"Halliburton, Inc. v. ARB","cite":"771 F.3d 254","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/771/254/","by":{"1":"30","2":"32, 33"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"op":1,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"1":"25","2":"1, 16, 19"}},{"t":"case","label":"Klopfenstein v. PCC Flow Techs. Holdings, Inc.","cite":"2006 WL 3246904","y":2006,"court":"ARB May 31","by":{"1":"30, 31","2":"46, 47"}},{"t":"case","label":"Kuduk v. BNSF Ry.","cite":"768 F.3d 786","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/786/","by":{"1":"33"}},{"t":"case","label":"Menendez v. Halliburton, Inc.","cite":"2011 WL 4915750","y":2011,"court":"ARB Sept. 13","by":{"1":"30"}},{"t":"case","label":"Mt. Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"ar":3,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"1":"2, 3"}},{"t":"case","label":"Rathburn v. Belt Ry.","cite":"2017 WL 6572154","y":2017,"court":"ARB Dec. 8","by":{"1":"33"}},{"t":"case","label":"Riley v. Dakota, Minn. & E. R.R.","cite":"2018 WL 6978216","y":2018,"court":"ARB July 6","by":{"1":"33"}},{"t":"case","label":"SEC v. Zandford","cite":"535 U.S. 813","y":2002,"id":"2001/01-147","sc":1,"sum":"The Court held that assuming that the complaint's allegations were true, the securities broker's conduct was in connection with the purchase or sale of any security.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Spadaro v. U.S. Dep’t of Interior","cite":"18 M.S.P.R. 462","y":1983,"url":"https://www.courtlistener.com/c/M.S.P.R./18/462/","by":{"1":"4"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Thorstenson v. BNSF Ry.","cite":"2019 WL 7042958","y":2019,"court":"ARB Nov. 25","ar":1,"by":{"1":"33, 34"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"31","2":"44"}},{"t":"case","label":"Warren v. Department of the Army","cite":"804 F.2d 654","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/804/654/","by":{"1":"4"}},{"t":"case","label":"Yowell v. Fort Worth & W. R.R.","cite":"2020 WL 3971213","y":2020,"court":"ARB Feb. 5","ar":1,"by":{"1":"34"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"2"}},{"t":"usc","label":"5 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/5/1101","by":{"1":"3"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)(1)(2006)"],"by":{"1":"19"}},{"t":"usc","label":"42 U.S.C. § 5801","url":"https://www.law.cornell.edu/uscode/text/42/5801","stext":{"head":"§5801. Congressional declaration of policy and purpose","paras":[[0,"(a) Development and utilization of energy sources"],[0,"The Congress hereby declares that the general welfare and the common defense and security require effective action to develop, and increase the efficiency and reliability of use of, all energy sources to meet the needs of present and future generations, to increase the productivity of the national economy and strengthen its position in regard to international trade, to make the Nation self-sufficient in energy, to advance the goals of restoring, protecting, and enhancing environmental quality, and to assure public health and safety."],[0,"(b) Necessity of establishing Energy Research and Development Administration"],[0,"The Congress finds that, to best achieve these objectives, improve Government operations, and assure the coordinated and effective development of all energy sources, it is necessary to establish an Energy Research and Development Administration to bring together and direct Federal activities relating to research and development on the various sources of energy, to increase the efficiency and reliability in the use of energy, and to carry out the performance of other functions, including but not limited to the Atomic Energy Commission's military and production activities and its general basic research activities. In establishing an Energy Research and Development Administration to achieve these objectives, the Congress intends that all possible sources of energy be developed consistent with warranted priorities."],[0,"(c) Separation of licensing and regulatory functions of Atomic Energy Commission"],[0,"The Congress finds that it is in the public interest that the licensing and related regulatory functions of the Atomic Energy Commission be separated from the performance of the other functions of the Commission, and that this separation be effected in an orderly manner, pursuant to this chapter, assuring adequacy of technical and other resources necessary for the performance of each."],[0,"(d) Small business participation"],[0,"The Congress declares that it is in the public interest and the policy of Congress that small business concerns be given a reasonable opportunity to participate, insofar as is possible, fairly and equitably in grants, contracts, purchases, and other Federal activities relating to research, development, and demonstration of sources of energy efficiency, and utilization and conservation of energy. In carrying out this policy, to the extent practicable, the Administrator shall consult with the Administrator of the Small Business Administration."],[0,"(e) Priorities"],[0,"Determination of priorities which are warranted should be based on such considerations as power-related values of an energy source, preservation of material resources, reduction of pollutants, export market potential (including reduction of imports), among others. On such a basis, energy sources warranting priority might include, but not be limited to, the various methods of utilizing solar energy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/5801?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5801. Congressional declaration of policy and purpose","tname":"The Public Health and Welfare","by":{"1":"7"}},{"t":"law","label":"and regulations—Continued: FDA Food Safety Modernization Act, Pub. L. No. 111-353","url":"https://www.govinfo.gov/link/plaw/111/public/353","by":{"1":"7"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","stext":{"head":"§301. Short title","paras":[[0,"This chapter may be cited as the Federal Food, Drug, and Cosmetic Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Short title","tname":"Food and Drugs","by":{"1":"7"}},{"t":"usc","label":"49 U.S.C. § 40122","url":"https://www.law.cornell.edu/uscode/text/49/40122","subs":["(g)(2)(A)"],"by":{"1":"2","2":"38"}},{"t":"case","label":"Addis v. Dep’t of Lab.","cite":"575 F.3d 688","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/688/","by":{"2":"43","3":"4"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"17, 28, 29"}},{"t":"case","label":"Armstrong v. BNSF Ry. Co.","cite":"880 F.3d 377","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/880/377/","by":{"2":"22"}},{"t":"case","label":"BFP v. Resol. Tr. Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Bhd. of R.R. Trainmen v. Balt. & Ohio R.R. Co.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"sum":"1. Under § 17 (11) of the Interstate Commerce Act, as amended by the Transportation Act of 1940, a union duly designated as the representative of employees of a railroad is given an absolute right, within the meaning of Rule 24 (a) (1) of the Federal Rules of Civil Procedure, to intervene in a suit brought under § 16 (12) to enjoin the railroad and its employees from violating an order of the Interstate Commerce …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Burlington Indus., Inc. v. Ellerth","cite":"524 U.S. 742","y":1998,"id":"1997/97-569","sc":1,"sum":"In a 7-to-2 opinion, the Court held that employers are vicariously liable for supervisors who create hostile working conditions for those over whom they have authority.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"sum":"Not under the CSC regulations. The federal judiciary, pursuant to its common law authority, has the power to recognize new causes of action in absence of, or to supplement, statutory remedies unless Congress has expressly indicated its relief is to be exclusive.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Clark v. Rameker","cite":"573 U.S. 122","y":2014,"id":"2013/13-299","sc":1,"sum":"The Court held that the U.S. Bankruptcy Code does not exempt inherited retirement accounts from a debtor's estate in bankruptcy proceedings.","sumSrc":"Oyez","by":{"2":"25, 35"}},{"t":"case","label":"Comcast Corp. v. Nat’l Ass’n of Afr. Am.Owned Media","cite":"140 S. Ct. 1009","y":2020,"id":"2019/18-1171","sc":1,"sum":"The Court held that a claim of race discrimination under 42 U.S.C. § 1981 requires that the plaintiff show that race was a but-for cause of the plaintiff's injury.","sumSrc":"Oyez","by":{"2":"23, 31"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Dir. of Revenue of Mo. v. CoBank ACB","cite":"531 U.S. 316","y":2001,"id":"2000/99-1792","sc":1,"sum":"The Court held that banks for cooperatives are subject to taxation. Justice Thomas wrote for the Court that nothing in the 1985 amendments to the Farm Credit Act indicated a repeal of the previous express approval of state taxation and that the structure of the Act indicated by negative implication that banks for cooperatives were not entitled to immunity.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Doyle v. Sec’y of Lab.","cite":"285 F.3d 243","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/285/243/","by":{"2":"43","3":"4"}},{"t":"case","label":"Dupree v. Younger","cite":"143 S. Ct. 1382","y":2023,"id":"2022/22-210","sc":1,"sum":"A post-trial motion under Federal Rule of Civil Procedure 50 is not required to preserve for appellate review a purely legal issue resolved at summary judgment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"48"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Genberg v. Porter","cite":"882 F.3d 1249","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/1249/","by":{"2":"23"}},{"t":"case","label":"Griggs v. Duke Power Co.","cite":"401 U.S. 424","y":1971,"id":"1970/124","sc":1,"sum":"After noting that Title VII of the Act intended to achieve equality of employment opportunities, the Court held that Duke's standardized testing requirement prevented a disproportionate number of African-American employees from being hired by, and advancing to higher-paying departments within, the company.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Hasan v. Dep’t of Lab.","cite":"400 F.3d 1001","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/1001/","by":{"2":"43","3":"4"}},{"t":"case","label":"Herb v. Pitcairn","cite":"324 U.S. 117","y":1945,"id":"scdb/1944-123","sc":1,"by":{"2":"50"}},{"t":"case","label":"Int’l Bhd. of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Kaufman v. Perez","cite":"745 F.3d 521","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/745/521/","by":{"2":"19, 43","3":"4"}},{"t":"case","label":"Lewis v. City of Chicago","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Loper Bright Enters., Inc. v. Raimondo","cite":"45 F.4th 359","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/359/","by":{"2":"44"}},{"t":"case","label":"Menendez v. Halliburton, Inc., ARB Case Nos. 09-002 & 09-003","cite":"2013 WL 1282255","y":2013,"court":"Mar. 15","sum":"Reasoning that evidence of the employer’s lack of retaliatory intent could not “address the issue of whether the [employer] would have disclosed [the employee’s] identity in the absence of his protected activity”.","sumSrc":"brief:2","by":{"2":"33"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Nat’l Ass’n of Greeting Card Publishers v. U.S. Postal Serv.","cite":"462 U.S. 810","y":1983,"id":"1982/81-1304","sc":1,"sum":"Section 3622(b) of the Postal Reorganization Act (Act) provides that the Postal Rate Commission shall recommend rates for the classes of mail in accordance with nine factors, the third of which (§3622(b)(3)) is \"the requirement that each class of mail or type of mail service bear the direct and indirect postal costs attributable to that class or type plus that portion of all other costs of the Postal Service …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"40, 41"}},{"t":"case","label":"Palmer v. Canadian Nat’l Ry./Ill. Cent. R.R. Co., ARB Case No. 16-035","cite":"2016 WL 5868560","y":2016,"court":"Sept. 30","by":{"2":"32"}},{"t":"case","label":"Pineda v. JTCH Apartments, LLC","cite":"843 F.3d 1062","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/843/1062/","sum":"Noting that “intentional torts” include “retaliatory discharge”.","sumSrc":"brief:2","by":{"2":"19"}},{"t":"case","label":"Proffitt v. FDIC","cite":"200 F.3d 855","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/200/855/","by":{"2":"45"}},{"t":"case","label":"Reeves v. Sanderson Plumbing Prods., Inc.","cite":"530 U.S. 133","y":2000,"id":"1999/99-536","sc":1,"sum":"The Court held that \"[a] plaintiff's prima facie case of discrimination, combined with sufficient evidence for a reasonable factfinder to reject the employer's nondiscriminatory explanation for its decision, may be adequate to sustain a finding of liability for intentional discrimination under the ADEA.\" The ruling means that an employer is liable to a former employee under the Age Discrimination in Employment Act of 1967 if a reasonable jury can find that the employer's explanation for the employee's dismissal was pretext for discrimination.","sumSrc":"Oyez","by":{"2":"17, 25"}},{"t":"case","label":"Reich v. Cambridgeport Air Sys., Inc.","cite":"26 F.3d 1187","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/26/1187/","by":{"2":"19"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"2":"15, 26, 31"}},{"t":"case","label":"Safe Food & Fertilizer v. EPA","cite":"350 F.3d 1263","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/350/1263/","by":{"2":"25"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Students for Fair Admissions, Inc. v. President & Fellows of Harvard Coll.","cite":"143 S. Ct. 2141","y":2023,"id":"2022/20-1199","sc":1,"sum":"The admissions programs at Harvard College and the University of North Carolina violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26"}},{"t":"case","label":"Texas Department of Community Affairs v. Burdine","cite":"450 U.S. 248","y":1981,"id":"1980/79-1764","sc":1,"op":2,"sum":"A case that held that the defendant bears the burden of proof to provide nondiscriminatory reasons for termination after a former employee has proven a prima facie case that the termination violated the Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"24, 25"}},{"t":"case","label":"Travis v. Gary Cmty. Mental Health Ctr., Inc.","cite":"921 F.2d 108","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/921/108/","sum":"Recognizing that “intentional torts” include “retaliatory discharge”.","sumSrc":"brief:2","by":{"2":"19"}},{"t":"case","label":"U.S. Postal Serv. Bd. of Governors v. Aikens","cite":"460 U.S. 711","y":1983,"id":"1982/81-1044","sc":1,"sum":"By framing the issue here in terms of whether a prima facie case is established by an employee's showing only that he was black, that he applied for a promotion for which he possessed the minimum qualifications, and that the employer selected a nonminority applicant, the parties and the Court of Appeals have unnecessarily evaded the ultimate question of discrimination vel non. By establishing a prima facie case, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"op":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Univ. of Tex. Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"2":"11, 16, 19, 22, 27, 28"}},{"t":"case","label":"Watson v. Fort Worth Bank & Tr.","cite":"487 U.S. 977","y":1988,"id":"1987/86-6139","sc":1,"op":2,"sum":"The judgment is vacated, and the case is remanded. 798 F. 2d 791, vacated and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, II-A, II-B, and III, concluding that disparate impact analysis may be applied to a subjective or discretionary promotion system. Pp. 985-991, 999-1000.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Young v. United Parcel Serv., Inc.","cite":"575 U.S. 206","y":2015,"id":"2014/12-1226","sc":1,"sum":"The Court held that the Pregnancy Discrimination Act requires courts to consider whether an employer’s policies treat pregnant workers less favorably than non-pregnant workers with similar inabilities to work and whether there are legitimate reasons for such differences.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"law","label":"Pub. L. No. 95-454","url":"https://www.govinfo.gov/link/statute/92/1111","by":{"2":"36"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","subs":["(a)(6)","(h)(1)(A)","(h)(1)(A)(i)"],"by":{"2":"44, 44, 44"}},{"t":"usc","label":"15 U.S.C. § 7202","url":"https://www.law.cornell.edu/uscode/text/15/7202","subs":["(a)"],"by":{"2":"44"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","by":{"2":"22, 23, 31"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"by":{"2":"22, 23, 31"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(2)(B)"],"by":{"2":"22, 23, 31"}},{"t":"usc","label":"41 U.S.C. § 4712","url":"https://www.law.cornell.edu/uscode/text/41/4712","subs":["(c)(6)"],"by":{"2":"37"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"2":"29"}},{"t":"reg","label":"29 C.F.R. § 1980.109","url":"https://www.ecfr.gov/current/title-29/section-1980.109","subs":["(a)"],"by":{"2":"46"}},{"t":"reg","label":"Delegation of Authority and Assignment of Responsibility to the Administrative Review Board, 85 Fed. Reg. 13186","url":"https://www.govinfo.gov/link/fr/85/13186","by":{"2":"45"}},{"t":"case","label":"14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"sum":"The Court held that arbitration clauses in employment contracts are enforceable as a matter of federal law.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"op":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"op":1,"ar":2,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Korslund v. DynCorp Tri-Cities Servs.","cite":"156 Wash.2d 168","y":2004,"url":"https://www.courtlistener.com/c/Wash.2d/156/168/","by":{"3":"14"}},{"t":"case","label":"iii Libby, McNeill & Libby v. United States","cite":"340 U.S. 71","y":1950,"id":"scdb/1950-008","sc":1,"sum":"\\,,overnment war \":Iconsequences ofrishkostiilnitsiuersanocrewpaorlliikcey insuring n operations\" ship against did not cover:i loss retsulting from the strinding of the insured ship (because of a inistake in steering) while it was (nglledin transp)orting milito rv suI)plies znd personnel between war bases, when there was in foet no (aiisal connection betweeni the \"warlike operation\" aul the stranding. 5tandard Oil …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4, 5"}},{"t":"case","label":"Palsgraf v. Long Island R. Co.","cite":"248 N.Y. 339","y":1928,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.Y./248/339/","by":{"3":"8-11"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Skinner v. Ry. Lab. Execs. Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"sum":"The Court held that the government's interest in assuring safety on the nation's railroads constituted a \"special need\" which justified a departure from standard warrant and probable-cause requirements in searches.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Territory of Guam v. United States","cite":"141 S. Ct. 1608","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"1, 2, 5"}},{"t":"case","label":"Trimmer v. Dep’t of Labor","cite":"174 F.3d 1098","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/174/1098/","by":{"3":"3"}},{"t":"reg","label":"48 Fed. Reg. 30726","url":"https://www.govinfo.gov/link/fr/48/30726","by":{"3":"5"}}]};